/**
 * The behaviour recipe engine (rich-behaviours brief, docs/ark/behaviour-recipes.md). Visual only:
 * the server's ecology decides every meal, birth and death.
 *
 * - Each species' recipes come from its stored text (`recipes.json`, generated by
 *   `scripts/ark-behaviour-recipes.mts`, with the phrase behind every recipe in
 *   `data/ark/behaviour-recipes.json`); the recipes are templates of building blocks
 *   (`recipe-templates.ts`, `behaviour-blocks.ts`).
 * - The schedule (`behaviour-schedule.ts`) asks `recipeIntent` for a slot's goal (a perch by the
 *   water, the water's edge, bare ground, its nest…), and `episodePose` lays the recipe's episode over
 *   its pose: an episode starts from the schedule's pose and blends back into it, so where a slot ends
 *   never changes.
 * - Pairs (rivals, a male and a female, two of a group) meet in windows of world time seeded by the
 *   pair, so both run one timeline; flocks (murmurations) by their leader.
 * - Deterministic and shared: every choice is seeded by ids, slots and the time. The same function
 *   runs near and far (positions and attitudes never jump between levels); near the camera the scene
 *   also draws what an episode carries, splashes, dirt and marks (`recipe-scene.ts`).
 *
 * Behaviour-only catches are ambient creatures only (decorative fish, insects, worms, shellfish): never a
 * catalogue animal, which only disappears through a server meal event.
 */

import table from "@/ark-scene/recipes.json";
import {BLOCKS, type BlockDef} from "@/ark-scene/behaviour-blocks";
import {AFTER_BLOCKS, ENTRY_BLOCKS, EXIT_BLOCKS, TEMPLATES, type AfterStyle, type CarryAt, type EntryStyle, type ExitStyle, type Posture, type PreyKind, type Target, type Template, type TemplateStep} from "@/ark-scene/recipe-templates";
import {bodyLengthsPerSecond, freeBodyLengthsPerSecond, runFactor, type ArkBehaviourProfile} from "@/ark-scene/behaviour-profile";
import type {ArkBeat, HoursAt, ScheduleAnimal, ScheduleWorld, Spot, Trip, TripMode, TripPose} from "@/ark-scene/behaviour-schedule";
import type {AttachPoint, AttachTag} from "@/ark-scene/world-sampler";
import {hashString} from "@/ark-scene/world";
import {buildQuarry, quarryAt, type QuarryLook, type QuarryNow, type QuarryTrack} from "@/ark-scene/recipe-hunt";

// MARK: Species data

export type SexSystem = "separate" | "workers" | "hermaphrodite" | "changes" | "parthenogenetic";
export type SpeciesRecipes = {
    slug: string;
    recipes: Array<{id: string; weight: number}>;
    sex: {system: SexSystem; maleShare: number; bigger: "male" | "female" | null; ratio: number; duller: "male" | "female" | null};
    /** Months (1–12) of its mating and nesting seasons; empty: none stored (all year, less often). */
    mating: number[];
    nesting: number[];
    nest: {kind: string; materials: string[]} | null;
    entry: EntryStyle;
    exit: ExitStyle;
    after: AfterStyle;
    posture: Posture | null;
    hovers: boolean;
    defaulted: boolean;
    /** Its recipe ids, for a quick "has it" (posing runs often). */
    has: ReadonlySet<string>;
};

const SYSTEMS: Record<string, SexSystem> = {s: "separate", w: "workers", h: "hermaphrodite", c: "changes", p: "parthenogenetic"};
const MONTH_LETTERS = "abcdefghijkl";
const ROWS = (table as {species: Record<string, string>}).species;
const decoded = new Map<string, SpeciesRecipes>();

export function decodeRecipeRow(slug: string, row: string): SpeciesRecipes {
    const [recipes = "", sex = "", mating = "", nesting = "", nest = "", cross = "", posture = "", flags = ""] = row.split("|");
    const [system = "s", share = "50", bigger = "-", ratio = "100", duller = "-"] = sex.split(":");
    const months = (s: string) => s.split("").map((c) => MONTH_LETTERS.indexOf(c) + 1).filter((m) => m > 0);
    const [nestKind, nestMaterials] = nest.split(":");
    const [entry = "wade", exit = "walk", after = "shake"] = cross.split(":");
    return {
        slug,
        recipes: recipes
            ? recipes.split(",").map((r) => {
                  const [id, w] = r.split(".");
                  return {id, weight: Number(w ?? 5) / 9};
              })
            : [],
        sex: {system: SYSTEMS[system] ?? "separate", maleShare: Number(share) / 100, bigger: bigger === "m" ? "male" : bigger === "f" ? "female" : null, ratio: Number(ratio) / 100, duller: duller === "m" ? "male" : duller === "f" ? "female" : null},
        mating: months(mating),
        nesting: months(nesting),
        nest: nestKind ? {kind: nestKind, materials: nestMaterials ? nestMaterials.split("+") : []} : null,
        entry: (entry as EntryStyle) || "wade",
        exit: (exit as ExitStyle) || "walk",
        after: (after as AfterStyle) || "shake",
        posture: (posture as Posture) || null,
        hovers: flags.includes("h"),
        defaulted: flags.includes("d"),
        has: new Set(recipes ? recipes.split(",").map((r) => r.split(".")[0]) : [])
    };
}

const NONE: Omit<SpeciesRecipes, "slug"> = {recipes: [], sex: {system: "separate", maleShare: 0.5, bigger: null, ratio: 1, duller: null}, mating: [], nesting: [], nest: null, entry: "wade", exit: "walk", after: "shake", posture: null, hovers: false, defaulted: true, has: new Set()};

export function speciesRecipes(slug: string): SpeciesRecipes {
    const hit = decoded.get(slug);
    if (hit) return hit;
    const row = ROWS[slug];
    const out = row ? decodeRecipeRow(slug, row) : {slug, ...NONE};
    decoded.set(slug, out);
    return out;
}

export function hasRecipes(slug: string): boolean {
    return slug in ROWS;
}

// MARK: Seeded sex

export type ArkSex = "male" | "female" | null;
export type SexLook = {sex: ArkSex; /** Drawn length factor (the species' mean stays the same). */ scale: number; /** Colour: 1 as drawn, less for the duller sex. */ saturation: number; value: number};

function unit(seed: string): number {
    return (hashString(seed) % 100_003) / 100_003;
}

/** Its seeded sex (the stored ratio; none for a hermaphrodite) and how that shows (size, a duller coat or plumage), from its id. */
export function sexLook(id: string, slug: string): SexLook {
    const s = speciesRecipes(slug).sex;
    if (s.system === "hermaphrodite") return {sex: null, scale: 1, saturation: 1, value: 1};
    const sex: ArkSex = unit(`${id}#sex`) < s.maleShare ? "male" : "female";
    const half = Math.sqrt(Math.max(s.ratio, 1));
    const scale = !s.bigger ? 1 : s.bigger === sex ? half : 1 / half;
    const dull = s.duller === sex;
    return {sex, scale, saturation: dull ? 0.72 : 1, value: dull ? 0.94 : 1};
}

// MARK: Seasons and hours

function monthAt(epochSeconds: number): number {
    return new Date(epochSeconds * 1000).getUTCMonth() + 1;
}

/** How much a season-bound template runs now: in season 1; out of it 0; no season stored, a little all year. */
export function seasonFactor(species: SpeciesRecipes, season: Template["season"], epochSeconds: number): number {
    if (!season) return 1;
    const months = season === "mating" ? species.mating : species.nesting;
    if (!months.length) return season === "nesting" ? 0 : 0.25;
    return months.includes(monthAt(epochSeconds)) ? 1 : 0;
}

function hourOk(template: Template, hours: number): boolean {
    switch (template.hours) {
        case "day":
            return hours > 6.3 && hours < 18.2;
        case "night":
            return hours < 5.2 || hours > 19.5;
        case "dawn_dusk":
            return (hours > 5.5 && hours < 9.5) || (hours > 16 && hours < 20);
        case "dusk":
            return hours > 17.4 && hours < 18.6;
        default:
            return true;
    }
}

// MARK: The schedule's kit (passed in by the schedule, so this module imports no schedule code)

export type ScheduleKit = {
    placeNear: (world: ScheduleWorld, centre: {x: number; z: number}, length: number, tags: AttachTag[], radius: number, roll: number) => AttachPoint | null;
    spotOf: (point: AttachPoint) => Spot;
    groundSpot: (world: ScheduleWorld, x: number, z: number) => Spot;
    rangeSpot: (world: ScheduleWorld, profile: ArkBehaviourProfile, animal: ScheduleAnimal, centre: {x: number; z: number}, radius: number, random: () => number) => Spot;
    waterSpot: (world: ScheduleWorld, profile: ArkBehaviourProfile, animal: ScheduleAnimal, x: number, z: number, random: () => number) => Spot;
    roostOf: (world: ScheduleWorld, profile: ArkBehaviourProfile, animal: ScheduleAnimal) => Spot;
    tripAt: (world: ScheduleWorld, profile: ArkBehaviourProfile, animal: ScheduleAnimal, epochSeconds: number, hoursAt: HoursAt, activity?: ArkBehaviourProfile["activity"] | null) => Trip;
    basePose: (world: ScheduleWorld, trip: Trip, epochSeconds: number) => TripPose;
    flies: (profile: ArkBehaviourProfile) => boolean;
    aquatic: (profile: ArkBehaviourProfile) => boolean;
    floats: (profile: ArkBehaviourProfile) => boolean;
};

function rng(seed: number): () => number {
    let s = seed >>> 0 || 1;
    return () => {
        s ^= s << 13;
        s ^= s >>> 17;
        s ^= s << 5;
        return ((s >>> 0) % 1_000_003) / 1_000_003;
    };
}

// MARK: Goals (the schedule's hook)

export type RecipeIntent = {doing: string; to: Spot; mode: TripMode; recipe: string};
export type RecipeIntentInput = {
    world: ScheduleWorld;
    profile: ArkBehaviourProfile;
    animal: ScheduleAnimal;
    slug: string;
    slot: number;
    start: number;
    hours: number;
    /** What the schedule picked (the behaviour and its doing): a recipe stands in for these only. */
    behaviour: string;
    doing: string;
    centre: {x: number; z: number};
    radius: number;
    kit: ScheduleKit;
};

/** On unless a page or a test turns it off. */
let enabled = true;
export function setRecipesEnabled(on: boolean) {
    enabled = on;
    forgetRecipes();
}
export function recipesEnabled(): boolean {
    return enabled;
}

/** A slot's goal for a recipe, or null (then the schedule's own choice stands). Pure in (id, slot, the hour). */
export function recipeIntent(input: RecipeIntentInput): RecipeIntent | null {
    if (!enabled) return null;
    const species = speciesRecipes(input.slug);
    if (!species.recipes.length) return null;
    const random = rng(hashString(`${input.animal.id}#recipe#${input.slot}`));
    const sex = sexLook(input.animal.id, input.slug).sex;
    for (const {id, weight} of species.recipes) {
        const template = TEMPLATES[id];
        if (!template || template.kind !== "stay" || template.goal === "here") continue;
        if (!template.replaces.includes(input.behaviour) && !template.replaces.includes(input.doing)) continue;
        if (!hourOk(template, input.hours)) continue;
        if (template.sex === "male" && sex === "female") continue;
        // With the props' nests wired, it builds while its nest is growing (their stage), whatever the months say.
        const building = id === "nest_build" && nestSource ? nestSource(input.animal.id, input.start) : null;
        if (id === "nest_build" && nestSource && (!building || building.stage >= 1)) continue;
        const chance = weight * 0.7 * (template.often ?? 1) * (building ? 1 : seasonFactor(species, template.season, input.start));
        if (random() >= chance) continue;
        const to = goalSpot(input, template, random);
        if (!to) continue;
        const flyer = input.kit.flies(input.profile);
        const raisedTo = to.y > Math.max(input.world.sampler.heightAt(to.x, to.z), 0) + 0.4;
        const mode: TripMode = input.kit.aquatic(input.profile) ? "water" : flyer && (raisedTo || template.goal === "perch_water" || template.goal === "nest") ? "air" : "ground";
        return {doing: template.doing, to, mode, recipe: id};
    }
    return null;
}

/**
 * A sitter with eggs (or chicks) in its nest sits on it: every slot goes to the nest (awake, it sits; asleep, it sleeps
 * there), from the props lane's nests (`setNestSource`; the eggs are the server's). Null for everyone else.
 */
export function sitterIntent(input: {world: ScheduleWorld; profile: ArkBehaviourProfile; animal: ScheduleAnimal; start: number; awake: boolean; kit: ScheduleKit}): RecipeIntent | null {
    if (!enabled || !nestSource) return null;
    const site = nestSource(input.animal.id, input.start);
    if (!site || !((site.eggs ?? 0) > 0 || (site.chicks ?? 0) > 0)) return null;
    const to: Spot = {x: site.x, y: site.y, z: site.z, nx: 0, ny: 1, nz: 0, point: null};
    const raisedTo = to.y > Math.max(input.world.sampler.heightAt(to.x, to.z), 0) + 0.4;
    const mode: TripMode = input.kit.flies(input.profile) && raisedTo ? "air" : input.kit.aquatic(input.profile) ? "water" : "ground";
    return {doing: input.awake ? "rest" : "sleep", to, mode, recipe: "incubate_sit"};
}

/** Open water near a point (deeper than `depth`), searched in seeded rings out to `reach`. */
function waterNear(world: ScheduleWorld, x: number, z: number, reach: number, depth: number, seed: number): {x: number; z: number; floor: number} | null {
    const turn = (seed % 360) * (Math.PI / 180);
    for (const f of [0.15, 0.3, 0.45, 0.6, 0.8, 1]) {
        const r = reach * f;
        for (let k = 0; k < 12; k++) {
            const a = turn + (k / 12) * Math.PI * 2;
            const px = x + Math.sin(a) * r;
            const pz = z + Math.cos(a) * r;
            const floor = world.sampler.heightAt(px, pz);
            if (floor < -depth) return {x: px, z: pz, floor};
        }
    }
    return null;
}

/** How high above the water a plunge-diver dives from (m): a kingfisher from a metre or so to a few, never off a cliff. */
function plungeDrops(length: number): [number, number] {
    return [Math.max(length * 4, 0.6), Math.min(Math.max(length * 40, 4), 12)];
}

/**
 * Whether a plunge from `from` to `to` stays in the air until it reaches the water: the dive's own path (most of the
 * way out early, the drop gathering at the end) never goes below the ground under it (a dive off a high bank into the
 * lake below goes through the bank).
 */
function clearPlunge(world: ScheduleWorld, from: P, to: P): boolean {
    for (let u = 0.1; u <= 0.85; u += 0.05) {
        const along = Math.min(u * 1.25, 1);
        const x = from.x + (to.x - from.x) * along;
        const z = from.z + (to.z - from.z) * along;
        const y = from.y + (to.y - from.y) * Math.pow(u, 1.6);
        if (y < Math.max(world.sampler.heightAt(x, z), 0) + 0.1) return false;
    }
    return true;
}

/** Open water a plunge-diver at `from` can dive into: within reach, deep enough, a drop it dives from and a clear way down. */
function plungeWater(world: ScheduleWorld, from: P, reach: number, length: number): P | null {
    const [low, high] = plungeDrops(length);
    if (from.y < low || from.y > high) return null;
    for (const f of [0.3, 0.5, 0.75, 1]) {
        for (let k = 0; k < 16; k++) {
            const a = (k / 16) * Math.PI * 2;
            const x = from.x + Math.sin(a) * reach * f;
            const z = from.z + Math.cos(a) * reach * f;
            if (world.sampler.heightAt(x, z) >= -0.45) continue;
            const to = {x, y: -Math.max(length * 0.3, 0.06), z};
            if (clearPlunge(world, from, to)) return to;
        }
    }
    return null;
}

function goalSpot(input: RecipeIntentInput, template: Template, random: () => number): Spot | null {
    const {world, profile, animal, kit, centre} = input;
    const length = Math.max(animal.length, 0.05);
    const radius = Math.max(input.radius, 2);
    switch (template.goal) {
        case "perch_water": {
            // A branch, a rock, a ledge or the reeds with open water below or near it (or a bank, failing that).
            // Low ones first (a kingfisher fishes from a metre or a few over the water), then any height.
            const reach = Math.min(Math.max(length * 40, 4), 14);
            const lowest = Math.min(Math.max(length * 20, 2.5), 8);
            for (const low of [true, false]) {
                for (const tag of ["branch", "reeds", "rock_top", "cliff_ledge"] as AttachTag[]) {
                    const near = world.sampler.attachPoints(tag, {x: centre.x, z: centre.z, r: radius * 1.6}).filter((p) => !low || p.y - Math.max(world.sampler.heightAt(p.x, p.z), 0) < lowest);
                    const sorted = [...near].sort((a, b) => Math.hypot(a.x - centre.x, a.z - centre.z) - Math.hypot(b.x - centre.x, b.z - centre.z) || a.id.localeCompare(b.id));
                    // (Open water below it and a clear drop: a perch on a high bank over the lake is no plunge perch.)
                    for (const point of sorted.slice(0, 24)) if (plungeWater(world, {x: point.x, y: point.y, z: point.z}, reach, length)) return kit.spotOf(point);
                }
            }
            const edge = kit.placeNear(world, centre, length, ["water_edge"], radius * 1.6, random());
            return edge ? kit.spotOf(edge) : null;
        }
        case "perch": {
            const point = kit.placeNear(world, centre, length, ["branch", "rock_top", "cliff_ledge", "reeds"], radius * 1.3, random());
            return point ? kit.spotOf(point) : null;
        }
        case "edge": {
            const point = kit.placeNear(world, centre, length, ["water_edge"], Math.min(radius * 1.8, 40), random());
            return point ? {...kit.spotOf(point), y: Math.max(world.sampler.heightAt(point.x, point.z), 0)} : null;
        }
        case "water": {
            if (kit.aquatic(profile) || kit.floats(profile) || profile.moves.includes("swim")) {
                const water = waterNear(world, centre.x, centre.z, Math.max(radius * 1.5, 6), Math.max(length * 0.8, 0.4), hashString(`${animal.id}#w#${input.slot}`));
                if (!water) return null;
                return kit.waterSpot(world, profile, animal, water.x, water.z, random);
            }
            // A flyer that fishes from the air starts from the shore.
            const edge = kit.placeNear(world, centre, length, ["water_edge"], Math.min(radius * 1.8, 40), random());
            return edge ? kit.spotOf(edge) : null;
        }
        case "ground":
        case "bare": {
            if (kit.aquatic(profile)) return null;
            const spot = kit.rangeSpot(world, profile, animal, centre, radius * 0.8, random);
            return world.sampler.heightAt(spot.x, spot.z) > 0.02 ? spot : null;
        }
        case "bark": {
            const point = kit.placeNear(world, centre, length, ["bark"], radius * 1.4, random());
            return point ? kit.spotOf(point) : null;
        }
        case "rock": {
            const point = kit.placeNear(world, centre, length, ["rock_top"], radius * 1.4, random());
            return point ? kit.spotOf(point) : null;
        }
        case "nest":
            return nestSiteOf(world, profile, animal, input.slug, kit, input.start);
        case "air": {
            // A place in the air over open ground or water near its range (a bat's beat): 3–6 m up.
            const a = random() * Math.PI * 2;
            const r = radius * (0.3 + 0.7 * random());
            const x = centre.x + Math.sin(a) * r;
            const z = centre.z + Math.cos(a) * r;
            return {x, y: Math.max(world.sampler.heightAt(x, z), 0) + 3 + random() * 3, z, nx: 0, ny: 1, nz: 0, point: null};
        }
        default:
            return null;
    }
}

// MARK: Other lanes' sources (wired by the scene once those lanes are in: see docs/ark/behaviour-recipes.md)

/** A nest the props lane draws for an animal (its site and how far built it is at a world time), or null. */
export type NestSource = (animalId: string, epochSeconds: number) => {x: number; y: number; z: number; stage: number; eggs?: number; chicks?: number} | null;
/** Ambient fish schools near a point at a world time (the reef lane's `fishSchoolsNear`). */
export type FishSource = (pos: {x: number; y?: number; z: number}, radius: number, epochSeconds: number) => Array<{centre: {x: number; y: number; z: number}; radius: number; heading: {x: number; y: number; z: number}; speed: number; mode: string}>;
let nestSource: NestSource | null = null;
let fishSource: FishSource | null = null;

/** The props lane's nests: a builder carries its material to the props' nest for it, and builds while that nest is growing. */
export function setNestSource(source: NestSource | null) {
    nestSource = source;
    forgetRecipes();
}
/** The reef lane's ambient schools: a chase goes after the nearest school (where it will be), a plunge into it. */
export function setFishSource(source: FishSource | null) {
    fishSource = source;
    forgetRecipes();
}
export function hasNestSource(): boolean {
    return Boolean(nestSource);
}
/** The wired nest source's site for an animal now (null without one). */
export function nestSourceOf(animalId: string, epochSeconds: number) {
    return nestSource ? nestSource(animalId, epochSeconds) : null;
}

let fallbackNestsOn: boolean | null = null;
/** Development: draw this branch's own growing nests even with a nest source wired (the clip page's stand-in props). */
export function setFallbackNests(on: boolean | null) {
    fallbackNestsOn = on;
}
/** Whether the scene draws this branch's own nests: until the props lane's are wired. */
export function fallbackNests(): boolean {
    return fallbackNestsOn ?? !nestSource;
}

/**
 * The adapter for the props lane (`props/nest-growth.ts`): its sites (`nestSites()`, with `sitter`) and stages
 * (`nestStage(speciesId, siteId, arkDay)`), and the Ark day at a world time. Pure, as the props' own schedule is.
 */
export function nestSourceFromProps(props: {sites: () => Array<{sitter: string | null; speciesId: string; siteId: string; position: {x: number; y: number; z: number}; eggs?: number; chicks?: number}>; stage: (speciesId: string, siteId: string, arkDay: number) => number; arkDayAt: (epochSeconds: number) => number}): NestSource {
    return (animalId, epochSeconds) => {
        const site = props.sites().find((s) => s.sitter === animalId);
        return site ? {...site.position, stage: props.stage(site.speciesId, site.siteId, props.arkDayAt(epochSeconds)), eggs: site.eggs ?? 0, chicks: site.chicks ?? 0} : null;
    };
}

// MARK: Nests

const nestSites = new Map<string, Spot | null>();

/** The year of a nesting season (the season's first month's year), so a nest site is new each season. */
function nestYear(species: SpeciesRecipes, epochSeconds: number): number {
    const date = new Date(epochSeconds * 1000);
    const first = species.nesting.length ? species.nesting[0] : 3;
    return date.getUTCMonth() + 1 >= first ? date.getUTCFullYear() : date.getUTCFullYear() - 1;
}

/**
 * Its nest site this season (deterministic per animal and season): a branch for a cup, dome or platform; a wall
 * or cliff for a mud nest; reeds or the water's edge for a floating nest; the ground (shade) for a scrape or a
 * mound; a hole in bark for a cavity. Null if it builds none.
 */
export function nestSiteOf(world: ScheduleWorld, profile: ArkBehaviourProfile, animal: ScheduleAnimal, slug: string, kit: ScheduleKit, epochSeconds: number): Spot | null {
    const props = nestSource ? nestSource(animal.id, epochSeconds) : null;
    if (props) return {x: props.x, y: props.y, z: props.z, nx: 0, ny: 1, nz: 0, point: null};
    const species = speciesRecipes(slug);
    if (!species.nest) return null;
    const key = `${animal.id}#${nestYear(species, epochSeconds)}`;
    if (nestSites.has(key)) return nestSites.get(key)!;
    const kind = species.nest.kind;
    // A low branch first (most stick and cup nests are within a few metres of the ground, and can be seen there).
    if (kit.flies(profile) && ["cup", "dome", "platform", "other"].includes(kind)) {
        const low = world.sampler
            .attachPoints("branch", {x: animal.home.x, z: animal.home.z, r: 14})
            .filter((p) => p.y - Math.max(world.sampler.heightAt(p.x, p.z), 0) < 5 && p.y - Math.max(world.sampler.heightAt(p.x, p.z), 0) > 1.2)
            .sort((a, b) => a.id.localeCompare(b.id));
        if (low.length) {
            const spot = kit.spotOf(low[Math.floor(rng(hashString(key))() * low.length)]);
            nestSites.set(key, spot);
            return spot;
        }
    }
    const tags: AttachTag[] =
        kind === "mud" ? ["house_wall", "cliff_ledge", "rock_face", "branch"] : kind === "floating" || kind === "bubble" ? ["reeds", "water_edge"] : kind === "cavity" ? ["bark", "branch"] : kind === "scrape" || kind === "mound" || kind === "burrow" ? ["shade", "grass"] : kit.flies(profile) ? ["branch", "reeds", "shade"] : ["shade", "grass"];
    const roll = rng(hashString(key))();
    const point = kit.placeNear(world, animal.home, Math.max(animal.length, 0.05), tags, 12, roll);
    const spot = point ? kit.spotOf(point) : kit.aquatic(profile) ? null : kit.groundSpot(world, animal.home.x + 0.8, animal.home.z + 0.6);
    nestSites.set(key, spot);
    return spot;
}

/** Days a nest takes to build (island days). */
export const NEST_BUILD_DAYS = 5;

/**
 * How far its nest is built (0–1) at a world time: through the first `NEST_BUILD_DAYS` of its nesting season it
 * grows; it stands for the rest of the season, then is gone. For the props lane's nest-stage interface.
 */
export function nestStageAt(slug: string, epochSeconds: number): number {
    const species = speciesRecipes(slug);
    if (!species.nest || !species.nesting.length) return 0;
    const date = new Date(epochSeconds * 1000);
    const month = date.getUTCMonth() + 1;
    if (!species.nesting.includes(month)) return 0;
    // Days since the season's first day (the months run in order, wrapping the year).
    const first = species.nesting[0];
    const year = month >= first ? date.getUTCFullYear() : date.getUTCFullYear() - 1;
    const start = Date.UTC(year, first - 1, 1) / 1000;
    const days = (epochSeconds - start) / 86_400;
    return Math.min(Math.max(days / NEST_BUILD_DAYS, 0), 1);
}

// MARK: Episodes

type P = {x: number; y: number; z: number};
export type Key = {
    t0: number;
    t1: number;
    block: BlockDef;
    from: P;
    to: P;
    /** Its heading as the key starts (where the last left it: nothing snaps). */
    yawIn: number;
    /** A hold's heading (it turns to it from `yawIn` at its turn rate); a leg's heading as it arrives. */
    yaw: number;
    /** A leg's curve: the control point it leaves by along `yawIn` (a curve, not a corner); null goes straight. */
    c: {x: number; z: number} | null;
    /** And the one it comes in by, when it arrives facing something (its rival, at the end of a walk to meet it). */
    c2: {x: number; z: number} | null;
    /** The last leg: how far back from its schedule's pose it lines up with that pose's heading (it arrives facing it). */
    endLen: number;
    /** Faces this point while it holds (a rival, the water). */
    face: P | null;
    carry: {item: PreyKind | "material" | "stick" | "stone"; at: CarryAt; material?: string} | null;
    catch: {kind: PreyKind; ok: boolean; at: P} | null;
    /** An ambient school or swarm near (the prey it chases or watches). */
    prey: {kind: PreyKind; at: P} | null;
    /** Its height above the ground there, for a wade (the feet on the bottom). */
    wade: boolean;
    /** The last key: to its schedule's live pose. */
    toBase: boolean;
    /** That last key goes to a fixed point: where its schedule will have it as the key ends (a pair's: its schedule walks on). */
    fixed?: boolean;
};

export type Episode = {
    id: string;
    recipe: string;
    t0: number;
    t1: number;
    keys: Key[];
    anchor: P;
    length: number;
    /** A pair's: the other and its role. */
    other?: string | null;
    role?: "a" | "b" | null;
    /** A stay's: the heading it comes home with. It keeps it until its slot ends (no turning round on the spot to face
     *  the way it first arrived), and its next slot sets off turning from it. Null: it turns into its schedule pose's. */
    endYaw?: number | null;
    /** And the way its next slot sets off: it turns to it on the spot in its stay's last seconds. */
    nextYaw?: number | null;
};

/** What a recipe adds to the pose: the block and state now, its attitude, what it carries, splashes and marks (near only). */
export type RecipeAct = {
    episode: string;
    recipe: string;
    block: string;
    /** The named animation state (the rig player's): `ARK_RECIPE_STATES`. */
    state: string;
    /** 0–1 through the block now. */
    u: number;
    pitch: number;
    roll: number;
    /** Its pose is its own (not the water band's), under the surface too. */
    own: boolean;
    carry: Key["carry"];
    prey: Key["prey"];
    /** A catch at this step: where and whether it came off. */
    catch: Key["catch"];
    fx: {kind: NonNullable<BlockDef["fx"]>; at: P; id: string; during: boolean; when: "start" | "end" | "during"} | null;
    mark: {kind: NonNullable<BlockDef["mark"]>; at: P; id: string; from: number} | null;
    label: string;
    /** A murmuration's centre and seed (the scene draws its ambient flockmates from the same function). */
    flock?: Flock | null;
    /** The ambient creature it is hunting now, where it is (`recipe-hunt.ts`): a grasshopper, a moth, a fish. */
    quarry?: QuarryNow | null;
    /** Its partner in a pair's act (a rival, a mate), by id: the collision lane lets the two close to contact. */
    with?: string | null;
};

/** Ambient flock-mates the scene draws round catalogue animals: a murmuration, a swarm, a crawling cluster, bats streaming out of a roost. */
export type Flock = {centre: P; seed: number; t0: number; t1: number; kind?: "murmuration" | "swarm" | "cluster" | "bats"};

export type RecipePose = TripPose & {act?: RecipeAct | null; /** Ambient flock-mates round it now (its act may be anything). */ flock?: Flock | null};

/** The owner a trip was worked out for (set by the schedule: its animal, profile, clock). */
export type TripOwner = {animal: ScheduleAnimal; profile: ArkBehaviourProfile; slug: string; activity: ArkBehaviourProfile["activity"] | null | undefined; hoursAt: HoursAt};

const stayEpisodes = new WeakMap<Trip, Episode | null>();
const pairEpisodes = new Map<string, Episode | null>();

export function forgetRecipes() {
    nestSites.clear();
    pairEpisodes.clear();
}

function pace(profile: ArkBehaviourProfile, length: number): number {
    return Math.max(bodyLengthsPerSecond(profile) * Math.max(length, 0.05), 0.08);
}

/**
 * A travel block's speed (m/s) for this animal, never faster than its clips carry it (behaviour's corrected clip
 * paces, so its feet never slide): walking at its walk's pace (`walk`, from `bodyLengthsPerSecond`), running at its
 * run's (`runFactor`: one with no run clip walks it), in the water at its schedule's own swimming pace (its free pace
 * times 1.4: a harbour seal chasing fish swam at a fixed 0.3 m/s, 2.1 times its clip's).
 */
function speedOf(block: BlockDef, walk: number, height: number, profile: ArkBehaviourProfile, length: number, fast = false): number {
    const runs = Math.min(runFactor(profile), 2.3);
    const swim = fast ? swimBurst(profile, length) : freeBodyLengthsPerSecond(profile) * Math.max(length, 0.05) * 1.4;
    switch (block.id) {
        case "run":
        case "flee":
            return walk * runs * (fast ? RUN_SPRINT : 1);
        case "clash":
            return walk * Math.min(runs, 2.1);
        case "stalk":
            return walk * 0.35;
        case "wade":
            return walk * 0.45;
        case "crawl":
            return walk * 0.6;
        case "carry":
        case "push":
            return walk * 0.8;
        case "climb":
            return walk * 0.5;
        case "swim":
        case "dive":
        case "surface":
            return Math.max(swim, 0.02);
        case "fly":
            return Math.min(Math.max(walk * 4, 2.5), 14) * (fast ? FLY_BURST : 1);
        case "dive_air":
        case "dive_feet":
            // Faster from higher up: a kingfisher's few metres at 6-8 m/s, a gannet's twenty-odd at 20.
            return Math.min(Math.max(4 + height * 0.9, 4), 20);
        default:
            return walk;
    }
}

/**
 * A hunt's fast legs (a template step's `fast`): the chase itself. Provisional until the locomotion lanes publish their
 * paces (L2 `swimPaces(...).burst`, `flightPaces(...).burst`; L1's sprint gait): a swimmer's burst is twice its cruise
 * (its tail beats faster with speed: the swim clip's rate follows the speed), a flyer's 1.6 times, a runner's sprint
 * 1.3 times its run (its run clip plays by the distance covered, so the feet keep up). Swapped in one place.
 */
export const SWIM_BURST = 2;
export const FLY_BURST = 1.6;
export const RUN_SPRINT = 1.3;
/** A burst is at least a body length a second (the rigs' swim clips are slow: a seal cruises at 0.17 m/s on its clip). */
export const SWIM_BURST_BL = 1;
/** A swimmer's burst at its prey (m/s): twice its cruise, at least a body length a second. */
export function swimBurst(profile: ArkBehaviourProfile, length: number): number {
    const l = Math.max(length, 0.05);
    return Math.max(freeBodyLengthsPerSecond(profile) * l * 1.4 * SWIM_BURST, l * SWIM_BURST_BL);
}

/** The block a "go" step resolves to: its own way of getting there. */
function goBlock(profile: ArkBehaviourProfile, kit: ScheduleKit, world: ScheduleWorld, from: P, to: P, length = 0): BlockDef {
    const flat = Math.hypot(to.x - from.x, to.z - from.z);
    const raisedTo = to.y > Math.max(world.sampler.heightAt(to.x, to.z), 0) + 0.4;
    const raisedFrom = from.y > Math.max(world.sampler.heightAt(from.x, from.z), 0) + 0.4;
    // (A swimmer that flies swims from water to water: a puffin or a duck does not take off to go a few metres.)
    const wet = world.sampler.heightAt(to.x, to.z) < -0.1 && world.sampler.heightAt(from.x, from.z) < -0.1;
    const swims = kit.aquatic(profile) || kit.floats(profile) || profile.moves.includes("swim");
    if (wet && !raisedTo && !raisedFrom && swims) return BLOCKS.swim;
    // (A bird walks or wades a few steps, as behaviour's own: further than that, or up or down, it flies.)
    if (kit.flies(profile) && (flat > Math.max(3, length * 6) || raisedTo || raisedFrom)) return BLOCKS.fly;
    if (kit.aquatic(profile) || wet) return swims ? BLOCKS.swim : BLOCKS.wade;
    if (raisedTo || raisedFrom) return BLOCKS.climb;
    return BLOCKS.walk;
}

type BuildContext = {
    world: ScheduleWorld;
    kit: ScheduleKit;
    owner: TripOwner;
    species: SpeciesRecipes;
    template: Template;
    anchor: P;
    t0: number;
    t1: number;
    seed: string;
    /** A pair: where the other starts, the role, the pair's own seed (both sides share timings). */
    pair?: {other: P; role: "a" | "b"; otherLength: number; pace: number} | null;
    hours: number;
    /** Its heading as the episode starts (its schedule pose's then): the first key turns from it, never from north. */
    yaw0: number;
    /** A stay that keeps the heading it comes home with (its leg home does not line up with the stay's heading). */
    holds?: boolean;
    /** Such a stay's last turn: on the spot at its slot's end (`slotEnd`), to the way its next slot sets off. */
    nextYaw?: number | null;
    slotEnd?: number;
    /** A pair: where its own schedule has it at a time (its way back joins it there, not a moving point). */
    homeAt?: (t: number) => P & {yaw: number};
    /** The heading its legs bend towards at a time (set by `buildEpisode`): one slow half loop over the episode, so it
     *  comes back round towards where it began instead of turning back on itself (an out-and-back is two U-turns). */
    plan?: (t: number) => number;
};

/** The animal's height (m), roughly, for wading depth and heights over water. */
const heightOf = (length: number) => Math.max(length * 0.6, 0.05);

/** How fast it turns on the spot (rad/s, at the eased turn's quickest): behaviour's TURN_RATE, its own set-off's. */
const TURN_SPOT = 1.6;

/** The most a solo episode's steps turn it in any 20 s before it heads home (rad: about half a circle, so its way home still fits). */
const TURN_BUDGET = 3.2;

/** The most it turns in any minute of a solo episode, with its way home (rad: under a full turn; a dabbling duck pivots, never spins). */
const MINUTE_BUDGET = 5.4;

/**
 * Legs on foot that drift forward as behaviour's grazers do (a forager's steps): each within a few degrees of its
 * heading (`DRIFT_SPREAD`), and anything over `DRIFT_TURN` off it turned on the spot first, standing, then straight on.
 */
const DRIFTS = new Set(["walk", "stalk", "crawl", "carry", "wade", "leap"]);
const DRIFT_SPREAD = 0.05;
const DRIFT_TURN = 0.2;

/** Whether a step drifts on so: a forager's legs on foot, and a short paddle or surfacing on from where it is (a dabbling duck). */
function driftsOn(step: TemplateStep, block: BlockDef, template?: Template): boolean {
    return DRIFTS.has(block.id) || ((step.near === "here" || Boolean(template?.drift)) && (block.id === "swim" || block.id === "surface"));
}

/** How far its body turns to face the water as it settles to watch it (rad): a heron's head does the rest. */
const WATCH_TURN = 0.35;

/** A solo leg further than this off its heading (rad) turns on the spot first, then sets off. */
const TURN_FIRST = 1.2;

/** Legs that turn on the spot first when they set off well away from the way it faces (not a flight, a take-off or a plunge). */
const TURNS_FIRST = new Set(["walk", "run", "flee", "stalk", "wade", "crawl", "carry", "push", "swim", "dive", "surface", "leap"]);

/** A last step home shorter than this (m) is a shuffle into place, keeping its heading. */
const SHUFFLE = 0.3;

/** About how long a leg of a recipe lasts at most (s): its reach is scaled to its pace. */
const LEG_SECONDS = 8;

/** A leg's length along its curve (m, flat; with the climb or drop). */
function legLength(from: P, c: {x: number; z: number} | null, c2: {x: number; z: number} | null, to: P): number {
    let flat = 0;
    let previous = {x: from.x, z: from.z};
    for (let j = 1; j <= 10; j++) {
        const at = legAt(from, c, c2, to, j / 10);
        flat += Math.hypot(at.x - previous.x, at.z - previous.z);
        previous = at;
    }
    return Math.hypot(flat, to.y - from.y);
}

const wrapAngle = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));

/** How fast it turns (rad/s, at the eased turn's quickest): a mouse quick, an elephant slow (behaviour's no-spin rule). */
export function turnRate(length: number): number {
    return Math.min(Math.max(1.8 / Math.pow(Math.max(length, 0.05), 0.4), 0.7), 3.5);
}

/** Its heading `elapsed` seconds into a turn from `from` to `to`: eased in and out, no quicker than its turn rate. */
function turned(from: number, to: number, elapsed: number, rate: number): number {
    return turnedBy(from, wrapAngle(to - from), elapsed, rate);
}

/** The same for a turn of `d` (signed, any size: a hook round may turn more than half a circle). */
function turnedBy(from: number, d: number, elapsed: number, rate: number): number {
    if (Math.abs(d) < 1e-4) return from;
    const span = (Math.abs(d) * 1.5) / rate;
    return from + d * ease(Math.min(Math.max(elapsed / span, 0), 1));
}

/**
 * A spot ahead of it, for a leg whose target is anywhere suitable round a centre (behaviour's no-spin rule): a chase
 * passes through and a forager goes on mostly forward, searching a little to either side. At the edge of its patch it
 * turns back across the patch (through the middle, never round the edge); where the water or ground ends ahead it
 * widens its turn. Null: nothing suitable ahead (the leg falls back to the old pick round its centre).
 */
function aheadSpot(ctx: BuildContext, step: TemplateStep, pos: P, heading: number, reach: number, spread: number, random: () => number, accept: (x: number, z: number) => P | null, t: number, drift = false): P | null {
    const here = step.near === "here";
    const len = reach * (here ? 0.6 + 0.4 * random() : 0.55 + 0.45 * random());
    const leash = here ? Math.max(reach * 6, 6) : Math.max(reach * 3, 12);
    // Ahead, bending a little towards the episode's slow loop.
    // (A forager on the ground drifts on: its loop bends it only a few degrees a step; bigger re-aims are on the spot.)
    const bend = drift ? spread * 1.5 : Math.max(spread * 1.5, 0.6);
    const aim = ctx.plan ? heading + Math.max(Math.min(wrapAngle(ctx.plan(t) - heading), bend), -bend) : heading;
    const anchor = ctx.anchor;
    const side = random() < 0.5 ? -1 : 1;
    const first = spread * (0.15 + 0.85 * random());
    const at = (a: number, f: number): P | null => {
        const x = pos.x + Math.sin(a) * len * f;
        const z = pos.z + Math.cos(a) * len * f;
        return Math.hypot(x - anchor.x, z - anchor.z) <= leash ? accept(x, z) : null;
    };
    for (const off of [first * side, -first * side * 0.7]) {
        for (const f of [1, 0.7]) {
            const p = at(aim + off, f);
            if (p) return p;
        }
    }
    // At the edge of its patch it bends back on the anchor's side, a wide turn (then straight across if it must).
    const homeward = Math.atan2(anchor.x - pos.x, anchor.z - pos.z);
    const toward = wrapAngle(homeward - heading) >= 0 ? 1 : -1;
    for (const off of drift && here ? [spread * 1.8, spread * 2.8] : [spread * 1.8, spread * 2.8, 0.9, 1.3]) {
        for (const f of [1, 0.7]) {
            const p = at(heading + off * toward, f);
            if (p) return p;
        }
    }
    // (A small step on with nothing ahead stays where it is: a heron at the end of its shallows stands and fishes on
    // there rather than turning round and back along them.)
    if (here) return null;
    if (Math.hypot(anchor.x - pos.x, anchor.z - pos.z) > len * 0.5) {
        for (const f of [1, 0.7]) {
            const p = at(homeward + first * side * 0.5, f);
            if (p) return p;
        }
    }
    for (const off of [spread * 1.8, spread * 2.8, Math.PI * 0.6, Math.PI * 0.85]) {
        for (const s of [side, -side]) {
            for (const f of [1, 0.6]) {
                const p = at(heading + off * s, f);
                if (p) return p;
            }
        }
    }
    return null;
}

/** The way a leg goes at `k` along it, as a turn from `start` (summed along the curve, so a hook of more than half a
 *  circle keeps turning the same way rather than flipping round). */
function legTurn(from: P, c: {x: number; z: number} | null, c2: {x: number; z: number} | null, to: P, k: number, start: number): number {
    let turn = 0;
    let previous = start;
    for (let j = 1; j <= 8; j++) {
        const at = legAt(from, c, c2, to, (k * j) / 8);
        if (Math.hypot(at.dx, at.dz) < 1e-6) continue;
        const a = Math.atan2(at.dx, at.dz);
        turn += wrapAngle(a - previous);
        previous = a;
    }
    return turn;
}

/** A point on a leg's curve (`c` null: straight), and its direction there. */
function legAt(from: P, c: {x: number; z: number} | null, c2: {x: number; z: number} | null, to: P, k: number): {x: number; z: number; dx: number; dz: number} {
    const j = 1 - k;
    if (c && c2) {
        return {
            x: j * j * j * from.x + 3 * j * j * k * c.x + 3 * j * k * k * c2.x + k * k * k * to.x,
            z: j * j * j * from.z + 3 * j * j * k * c.z + 3 * j * k * k * c2.z + k * k * k * to.z,
            dx: 3 * j * j * (c.x - from.x) + 6 * j * k * (c2.x - c.x) + 3 * k * k * (to.x - c2.x),
            dz: 3 * j * j * (c.z - from.z) + 6 * j * k * (c2.z - c.z) + 3 * k * k * (to.z - c2.z)
        };
    }
    if (c) return {x: j * j * from.x + 2 * j * k * c.x + k * k * to.x, z: j * j * from.z + 2 * j * k * c.z + k * k * to.z, dx: 2 * j * (c.x - from.x) + 2 * k * (to.x - c.x), dz: 2 * j * (c.z - from.z) + 2 * k * (to.z - c.z)};
    return {x: from.x + (to.x - from.x) * k, z: from.z + (to.z - from.z) * k, dx: to.x - from.x, dz: to.z - from.z};
}

/**
 * How far along its heading a leg leaves (its curve's control point), so it curves on from the way it was going rather
 * than turning on the spot: shorter where the curve would leave the water it swims in or the ground it walks on.
 * `endYaw`: it also arrives along that heading (its schedule's, on the way back), so it needs no turn there either.
 */
function legCurve(world: ScheduleWorld, block: BlockDef, from: P, to: P, heading: number, endYaw: number | null, lineUpWithin = Math.PI / 3): {c: {x: number; z: number}; c2: {x: number; z: number} | null; len: number} | null {
    const flat = Math.hypot(to.x - from.x, to.z - from.z);
    if (flat < 0.05) return null;
    const sampler = world.sampler;
    const wet = (x: number, z: number) => sampler.heightAt(x, z) < -0.02;
    const dry = !(wet(from.x, from.z) && wet(to.x, to.z)) && onGround(block);
    const medium = block.aloft || block.id === "fly" ? null : !dry ? (wet(from.x, from.z) && wet(to.x, to.z) ? wet : null) : (x: number, z: number) => walkableAt(world, x, z);
    const clear = (c: {x: number; z: number} | null, c2: {x: number; z: number} | null) => !medium || wayClear(from, c, c2, to, medium, dry);
    // Lining up with the end heading only where it comes in from behind that heading: from in front it would loop round
    // to come in (it turns at the end instead, at its turn rate).
    const chord = Math.atan2(to.x - from.x, to.z - from.z);
    const lineUp = endYaw !== null && Math.abs(wrapAngle(endYaw - chord)) < lineUpWithin ? endYaw : null;
    // Behind it, the control point goes out to the side it turns to: a hook round, not a curve that folds back on
    // itself (there the way it goes flips in an instant).
    const turn = wrapAngle(chord - heading);
    const side = Math.abs(turn) > 1.6 ? Math.sign(turn) * 0.9 : 0;
    for (const f of [0.4, 0.2, 0.1]) {
        const len = flat * f;
        const c = {x: from.x + Math.sin(heading) * len + Math.cos(heading) * len * side, z: from.z + Math.cos(heading) * len - Math.sin(heading) * len * side};
        const c2 = lineUp === null ? null : {x: to.x - Math.sin(lineUp) * len, z: to.z - Math.cos(lineUp) * len};
        if (clear(c, c2)) return {c, c2, len: c2 ? len : 0};
    }
    // Something in the way (the garden pond, a rock, a building): round it on one side or the other, a gentle arc.
    if (medium && !clear(null, null)) {
        for (const bow of [0.25, -0.25, 0.45, -0.45, 0.7, -0.7, 1, -1]) {
            const c = {x: (from.x + to.x) / 2 + Math.cos(chord) * flat * bow, z: (from.z + to.z) / 2 - Math.sin(chord) * flat * bow};
            if (clear(c, null)) return {c, c2: null, len: 0};
        }
    }
    return null;
}

/** On the ground, where the nav's walk grid governs (not in the air, the water or a plunge). */
function onGround(block: BlockDef): boolean {
    return !block.aloft && !block.wet && block.id !== "fly" && block.id !== "swim" && block.id !== "dive" && block.id !== "surface";
}

/**
 * The collision lane's colliders (L5, `@/ark-scene/collide`: fences, buildings and keep-outs, trunks, drawn rocks, logs,
 * bales), wired by the scene with `setRecipeColliders` once that lane is in. Without them the nav's walk grid and the
 * sampler's `blocked` stand alone, as before. Thin fences fall between point samples, so a ground leg's way is also
 * checked segment by segment along its curve (`segmentClear`).
 */
export type RecipeColliders = {
    segmentClear: (ax: number, az: number, bx: number, bz: number, radius: number) => boolean;
    blocked?: (x: number, z: number, radius: number) => boolean;
};
let colliders: RecipeColliders | null = null;
export function setRecipeColliders(source: RecipeColliders | null) {
    colliders = source;
    forgetRecipes();
}
/** A recipe leg's body radius against the colliders (the walk grid's 0.2 m for small ones). */
const LEG_RADIUS = 0.2;

/** Ground a walker may cross: the nav's own rule (a dry walkable cell, nothing in the way: the garden pond, a rock, a building). */
function walkableAt(world: ScheduleWorld, x: number, z: number): boolean {
    return world.nav.walkable(x, z) && !world.sampler.blocked(x, z, 0.2) && !(colliders?.blocked?.(x, z, LEG_RADIUS) ?? false);
}

/** Whether a leg's way, sampled every quarter metre or so, stays where `ok` says (and, on the ground, crosses no collider). */
function wayClear(from: P, c: {x: number; z: number} | null, c2: {x: number; z: number} | null, to: P, ok: (x: number, z: number) => boolean, ground = false): boolean {
    const n = Math.min(Math.max(Math.ceil(Math.hypot(to.x - from.x, to.z - from.z) / 0.25), 3), 60);
    let last = {x: from.x, z: from.z};
    for (let j = 1; j <= n; j++) {
        const at = j === n ? {x: to.x, z: to.z} : legAt(from, c, c2, to, j / n);
        if (j < n && !ok(at.x, at.z)) return false;
        if (ground && colliders && !colliders.segmentClear(last.x, last.z, at.x, at.z, LEG_RADIUS)) return false;
        last = at;
    }
    return true;
}

/** A ground way: the walk grid's cells and the colliders between them. */
function groundWay(world: ScheduleWorld, from: P, c: {x: number; z: number} | null, c2: {x: number; z: number} | null, to: P): boolean {
    return wayClear(from, c, c2, to, (x, z) => walkableAt(world, x, z), true);
}

/** A ground leg cut short where something blocks its way (it stops at the edge, never crosses). */
function clippedAtEdge(world: ScheduleWorld, from: P, to: P): P {
    const flat = Math.hypot(to.x - from.x, to.z - from.z);
    const n = Math.min(Math.max(Math.ceil(flat / 0.2), 2), 80);
    let last = from;
    for (let j = 1; j <= n; j++) {
        const x = from.x + ((to.x - from.x) * j) / n;
        const z = from.z + ((to.z - from.z) * j) / n;
        if (!walkableAt(world, x, z) || (colliders && !colliders.segmentClear(last.x, last.z, x, z, LEG_RADIUS))) return last;
        last = {x, y: Math.max(world.sampler.heightAt(x, z), 0), z};
    }
    return to;
}

function resolveTarget(ctx: BuildContext, step: TemplateStep, block: BlockDef, pos: P, random: () => number, heading: number, t: number): P | null {
    const {world, owner, anchor} = ctx;
    const length = Math.max(owner.animal.length, 0.05);
    // A leg reaches no further than it goes in about eight seconds at its own pace (a seal's slow clip chases close by).
    const within = (reach: number) => Math.min(reach, Math.max(speedOf(block, pace(owner.profile, length), 0, owner.profile, length) * LEG_SECONDS, length * 2, 0.6));
    const origin = step.near === "here" ? pos : anchor;
    const scaleUp = Math.min(Math.max(length / 0.4, 0.4), 2.2);
    const sampler = world.sampler;
    const ground = (x: number, z: number) => Math.max(sampler.heightAt(x, z), 0);
    switch (step.to) {
        case undefined:
        case "here":
            return pos;
        case "anchor":
            return anchor;
        case "up":
            return {x: pos.x, y: pos.y + (step.h ?? 1) * scaleUp, z: pos.z};
        case "prey":
        case "water":
        case "over_water": {
            // The reef lane's schools, where wired: the nearest one, where it will be when it gets there.
            if (fishSource && (step.to === "prey" || block.id === "dive_air" || block.id === "dive_feet")) {
                const school = fishSource(origin, Math.max(step.r ?? 12, 8), ctx.t0)[0];
                if (school) {
                    const lead = Math.min(Math.hypot(school.centre.x - pos.x, school.centre.z - pos.z) / Math.max(speedOf(block, pace(owner.profile, length), 0, owner.profile, length), 0.5), 6);
                    const x = school.centre.x + school.heading.x * school.speed * lead;
                    const z = school.centre.z + school.heading.z * school.speed * lead;
                    if (sampler.heightAt(x, z) < -0.25) return {x, y: step.to === "prey" ? Math.min(school.centre.y, -0.2) : -Math.max(length * 0.3, 0.06), z};
                }
            }
            // A dive goes into open water (not the edge's few centimetres); a chase deeper still.
            const depth = step.to === "prey" ? Math.max(length * 1.2, 0.5) : block.id === "dive_air" || block.id === "dive_feet" ? 0.45 : 0.25;
            const reach = within(Math.max(step.r ?? Math.min(Math.max(length * 40, 4), 14), 1.5));
            const under = block.id === "dive_air" || block.id === "dive_feet" ? -Math.max(length * 0.3, 0.06) : 0;
            const inWater = (x: number, z: number, floor: number): P =>
                step.to === "over_water" ? {x, y: (step.h ?? 4) * scaleUp, z} : step.to === "prey" ? {x, y: Math.max(floor + length * 0.6, -Math.max(length * 2.5, 1.2)) * (0.5 + 0.4 * random()), z} : {x, y: under, z};
            // (A plunge goes only where its way down is clear of the ground: else null, and it hovers out over the water first.)
            const plunge = block.id === "dive_air" || block.id === "dive_feet";
            const drifts = !ctx.pair && driftsOn(step, block, ctx.template);
            const ahead = aheadSpot(ctx, step, pos, heading, reach, drifts ? DRIFT_SPREAD : step.to === "prey" ? 0.2 : 0.3, random, (x, z) => {
                const floor = sampler.heightAt(x, z);
                if (floor >= -depth) return null;
                const at = inWater(x, z, floor);
                return !plunge || clearPlunge(world, pos, at) ? at : null;
            }, t, drifts);
            if (ahead) return ahead;
            if (step.near === "here") return pos;
            if (plunge) return plungeWater(world, pos, reach, length);
            const water = waterNear(world, origin.x, origin.z, reach, depth, hashString(`${ctx.seed}#${Math.floor(random() * 1e6)}`));
            if (!water) return null;
            return inWater(water.x, water.z, water.floor);
        }
        case "shallows": {
            const deepest = Math.min(Math.max(heightOf(length) * 0.45, 0.04), 0.7);
            const reach = within(step.r ?? Math.max(length * 6, 2.5));
            const drifts = !ctx.pair && driftsOn(step, block, ctx.template);
            const ahead = aheadSpot(ctx, step, pos, heading, reach, drifts ? DRIFT_SPREAD : 0.35, random, (x, z) => {
                const h = sampler.heightAt(x, z);
                return h < -0.02 && h > -deepest ? {x, y: h, z} : null;
            }, t, drifts);
            if (ahead) return ahead;
            if (step.near === "here") return pos;
            const turn = random() * Math.PI * 2;
            for (const f of [0.25, 0.5, 0.75, 1, 1.4]) {
                for (let k = 0; k < 10; k++) {
                    const a = turn + (k / 10) * Math.PI * 2;
                    const x = origin.x + Math.sin(a) * reach * f;
                    const z = origin.z + Math.cos(a) * reach * f;
                    const h = sampler.heightAt(x, z);
                    if (h < -0.02 && h > -deepest) return {x, y: h, z};
                }
            }
            return null;
        }
        case "edge": {
            const near = sampler.attachPoints("water_edge", {x: origin.x, z: origin.z, r: 18});
            if (!near.length) return null;
            const best = [...near].sort((a, b) => Math.hypot(a.x - origin.x, a.z - origin.z) - Math.hypot(b.x - origin.x, b.z - origin.z) || a.id.localeCompare(b.id))[0];
            return {x: best.x, y: ground(best.x, best.z), z: best.z};
        }
        case "ground":
        case "material": {
            const centre = step.to === "material" ? nestOrigin(ctx) ?? origin : origin;
            const reach = within(step.r ?? 3);
            // (Material too is gathered ahead, round the nest: each trip goes out on through the nest, not back and forth.)
            // (Only where its way there is clear ground: never across the garden pond, a rock or a building.)
            // (A pounce too: it does not leap a fence or a rock to land on its prey.)
            const reachable = (x: number, z: number) => sampler.heightAt(x, z) > 0.03 && walkableAt(world, x, z) && ((block.aloft && block.id !== "leap") || groundWay(world, pos, null, null, {x, y: 0, z}));
            const drifts = !ctx.pair && driftsOn(step, block, ctx.template);
            const ahead = aheadSpot(ctx, step, pos, heading, step.to === "material" ? reach * 0.6 : reach, drifts ? DRIFT_SPREAD : block.id === "leap" ? 0.2 : 0.3, random, (x, z) => (reachable(x, z) ? {x, y: ground(x, z), z} : null), t, drifts);
            if (ahead) return ahead;
            if (step.near === "here" && step.to === "ground") return pos;
            for (let k = 0; k < 10; k++) {
                const a = random() * Math.PI * 2;
                const r = reach * (0.35 + 0.65 * Math.sqrt(random()));
                const x = centre.x + Math.sin(a) * r;
                const z = centre.z + Math.cos(a) * r;
                if (reachable(x, z)) return {x, y: ground(x, z), z};
            }
            return null;
        }
        case "air": {
            const ahead = aheadSpot(ctx, step, pos, heading, within(step.r ?? 3), 0.35, random, (x, z) => ({x, y: origin.y + (random() - 0.3) * 1.2, z}), t);
            if (ahead) return ahead;
            if (step.near === "here") return pos;
            const a = random() * Math.PI * 2;
            const r = (step.r ?? 3) * (0.5 + 0.5 * random());
            return {x: origin.x + Math.sin(a) * r, y: origin.y + (random() - 0.3) * 1.2, z: origin.z + Math.cos(a) * r};
        }
        case "nest": {
            const nest = nestOrigin(ctx);
            return nest ?? null;
        }
        case "beach": {
            const reach = step.r ?? 6;
            const turn = random() * Math.PI * 2;
            for (let k = 0; k < 16; k++) {
                const a = turn + (k / 16) * Math.PI * 2;
                const x = origin.x + Math.sin(a) * reach;
                const z = origin.z + Math.cos(a) * reach;
                const h = sampler.heightAt(x, z);
                if (h > 0.05 && h < 1.6 && world.nav.walkable(x, z)) return {x, y: h, z};
            }
            return null;
        }
        case "meet":
        case "meet_far":
        case "meet_side":
        case "away": {
            const pair = ctx.pair;
            if (!pair) return pos;
            const own = ctx.anchor;
            const other = pair.other;
            const dx = other.x - own.x;
            const dz = other.z - own.z;
            const d = Math.hypot(dx, dz) || 1;
            const ux = dx / d;
            const uz = dz / d;
            const midX = (own.x + other.x) / 2;
            const midZ = (own.z + other.z) / 2;
            const both = Math.max(length, pair.otherLength);
            // Each keeps to its own side of the middle (u points from it to the other), so the two meet head-on; the
            // parallel walk goes the same way for both (role "b" turns its own perpendicular round), a body width apart.
            if (step.to === "away") {
                // (Back the way it came, no further than where it started: its way home after is short, not a turn back.)
                const back = Math.min(both * 5, Math.max((pos.x - own.x) * ux + (pos.z - own.z) * uz, both));
                const x = pos.x - ux * back;
                const z = pos.z - uz * back;
                return {x, y: ground(x, z), z};
            }
            if (step.to === "meet_side") {
                const along = pair.role === "a" ? 1 : -1;
                const x = midX + uz * along * both * 4 - ux * both * 0.6;
                const z = midZ - ux * along * both * 4 - uz * both * 0.6;
                return {x, y: ground(x, z), z};
            }
            // (The stand-off no further back than where it started: rivals already close do not back away to come again.)
            const gap = step.to === "meet" ? both * 0.42 : Math.min(both * 2.4, d / 2);
            const x = midX - ux * gap;
            const z = midZ - uz * gap;
            return {x, y: ground(x, z), z};
        }
        default:
            return pos;
    }
}

function nestOrigin(ctx: BuildContext): P | null {
    const spot = nestSiteOf(ctx.world, ctx.owner.profile, ctx.owner.animal, ctx.owner.slug, ctx.kit, ctx.t0);
    return spot ? {x: spot.x, y: spot.y, z: spot.z} : null;
}

/** The sun's bearing (yaw) at an hour: east in the morning, south at noon, west in the evening. */
function sunYaw(hours: number): number {
    return Math.PI / 2 - ((hours - 6) / 12) * Math.PI;
}

/** An episode's keys: the template's steps (then its loop while time allows, then its tail), each placed in the world from where the last left it. */
function buildEpisode(ctx: BuildContext): Episode | null {
    const {owner, template, species, world, kit} = ctx;
    const length = Math.max(owner.animal.length, 0.05);
    const random = rng(hashString(ctx.seed));
    // A pair's timings come from the pair (both sides draw the same lengths); its targets from each side's own place.
    const timing = ctx.pair ? rng(hashString(`${ctx.seed}#timing`)) : random;
    const keys: Key[] = [];
    const walk = ctx.pair ? ctx.pair.pace : pace(owner.profile, length);
    let t = ctx.t0;
    let pos: P = ctx.anchor;
    // Its heading as each key starts: from its schedule pose's, turned only by its legs' curves and its holds' eased turns.
    let yaw = ctx.yaw0;
    // Its legs bend round one slow half loop (a side for the episode): out, round and back towards where it began, so
    // its way home at the end lies ahead of it, not behind.
    const loopSide = hashString(`${ctx.seed}#loop`) % 2 ? 1 : -1;
    const loopCtx: BuildContext = {...ctx, plan: (at: number) => ctx.yaw0 + loopSide * Math.PI * Math.min(Math.max((at - ctx.t0) / Math.max(ctx.t1 - ctx.t0, 1), 0), 1)};
    const rate = turnRate(length);
    let carry: Key["carry"] = null;
    let caught = false;
    const material = species.nest?.materials[0] ?? "twigs";
    const reserve = 4;
    // (Its way home is its tail's own, when the tail goes back to where it began: a heron wades out, not walks.)
    const tailStep = template.tail?.find((step) => step.to === "anchor");
    const tailHome = tailStep && BLOCKS[tailStep.b] && tailStep.b !== "go" ? BLOCKS[tailStep.b] : null;
    // Its turning over the last 20 s (behaviour's circling measure): a step that would take it past the budget ends the
    // loop instead, and it heads home with one turn (a puffin in the shallows turned round to dive back, then again for home).
    const turns: Array<{t: number; turn: number}> = [];
    // (A pair: whether it has just squared up to its rival, so its next walk, to it, already faces its way.)
    let facingRival = false;
    const sequence = (steps: TemplateStep[], budgeted = true): boolean => {
        for (const step of steps) {
            const before = {n: keys.length, t, pos, yaw, carry, caught};
            const draw = step.s ? step.s[0] + (step.s[1] - step.s[0]) * timing() : 0;
            if (step.role && ctx.pair && step.role !== ctx.pair.role) {
                // The other role's step: this side holds for the same time (so both stay in step).
                if (draw > 0) {
                    if (t + draw > ctx.t1 - reserve) return false;
                    const want = Math.atan2(ctx.pair.other.x - pos.x, ctx.pair.other.z - pos.z);
                    keys.push({t0: t, t1: t + draw, block: BLOCKS.rest, from: pos, to: pos, yawIn: yaw, yaw: want, c: null, c2: null, endLen: 0, face: ctx.pair.other, carry, catch: null, prey: null, wade: false, toBase: false});
                    yaw = turned(yaw, want, draw, rate);
                    t += draw;
                }
                continue;
            }
            if (step.if === "caught" && !caught) continue;
            if (step.if === "hovers" && !species.hovers) continue;
            let block = BLOCKS[step.b];
            if (!block) continue;
            // (A strike lunges forward its own reach, a third of a body or so: it goes on from there.)
            // (No quicker than it runs: a slow-clipped animal strikes with its head, the body barely moving.)
            const lunge = block.id === "strike" ? Math.min((block.surge ?? 0.3) * length, 0.8, walk * Math.min(runFactor(owner.profile), 2.3) * (step.s ? step.s[0] : 0.4)) : 0;
            let target = block.motion === "travel" ? resolveTarget(loopCtx, step, block, pos, random, yaw, t) : lunge ? {x: pos.x + Math.sin(yaw) * lunge, y: pos.y, z: pos.z + Math.cos(yaw) * lunge} : pos;
            // A plunge from too low, too high or with ground in the way: it flies out over the water, hovers, and plunges
            // from there (as a kingfisher does where there is no perch over the water).
            if ((block.id === "dive_air" || block.id === "dive_feet") && (!target || pos.y < plungeDrops(length)[0] || pos.y > plungeDrops(length)[1])) {
                const hoverAt = Math.min(Math.max(length * 15, 1.5), 6) / Math.min(Math.max(length / 0.4, 0.4), 2.2);
                if (!sequence([{b: "fly", to: "over_water", h: hoverAt, r: step.r}, {b: "hover", s: [1, 2.5]}])) return false;
                target = resolveTarget(loopCtx, step, block, pos, random, yaw, t);
            }
            if (!target) return false;
            if (block.id === "go") block = goBlock(owner.profile, kit, world, pos, target, length);
            // A ground leg whose way is blocked (the garden pond, a rock, a building) and that no arc gets round stops at the edge.
            if (block.motion === "travel" && onGround(block) && Math.hypot(target.x - pos.x, target.z - pos.z) > 0.05 && walkableAt(world, pos.x, pos.z)) {
                const from = pos;
                if (!groundWay(world, from, null, null, target) && !legCurve(world, block, from, target, yaw, null)) target = clippedAtEdge(world, from, target);
            }
            const distance = Math.hypot(target.x - pos.x, target.y - pos.y, target.z - pos.z);
            const height = Math.max(pos.y - target.y, 0);
            const travelSeconds =
                block.id === "take_off"
                    ? 0.45 + 0.1 * timing()
                    : block.id === "land"
                      ? 0.6
                      : block.id === "leap" || block.id === "dive_in" || block.id === "hop_out"
                        ? 0.5 + 0.25 * timing()
                        : // A pair's travel times come from the pair's geometry (the same for both sides) at the slower one's pace;
                          // rivals walk up to each other slowly and stiffly (half their walk).
                          (ctx.pair ? Math.hypot(target.x - pos.x, target.z - pos.z) : distance) / (speedOf(block, walk, height, owner.profile, length, step.fast) * (ctx.pair && !step.role && block.id === "walk" ? 0.5 : 1));
            const flat = Math.hypot(target.x - pos.x, target.z - pos.z);
            const face: P | null = step.face === "other" && ctx.pair ? ctx.pair.other : step.face === "water" ? waterFace(world, pos, length, yaw) : null;
            // Its heading (behaviour's no-spin rule): a leg curves on from the way it was going and it faces along the
            // curve; a hold keeps the heading it came in on, or turns at its turn rate to what it faces (the water, the
            // sun, its rival); a charge turns to its rival as it goes. Nothing snaps.
            // Well away from the way it faces, it turns on the spot first at its turn rate, then sets off nearly straight (a
            // stalk round behind it was a slow loop).
            // A pair's walk that does not follow squaring up turns on the spot first for the same time on both sides (one
            // timeline); its loser's run off, its own step, turns as a solo leg does.
            const swing = block.motion === "travel" && (!ctx.pair || step.role) && flat > 0.03 && TURNS_FIRST.has(block.id) ? wrapAngle(Math.atan2(target.x - pos.x, target.z - pos.z) - yaw) : 0;
            const pairTurn = ctx.pair && !step.role && block.motion === "travel" && block.id !== "clash" && flat > 0.03 && !facingRival;
            const turnFirst = pairTurn
                ? (Math.PI * 1.5) / Math.min(turnRate(Math.max(length, ctx.pair!.otherLength)), TURN_SPOT)
                : Math.abs(swing) > (driftsOn(step, block, ctx.template) ? DRIFT_TURN : TURN_FIRST)
                  ? (Math.abs(swing) * 1.5) / Math.min(rate, TURN_SPOT)
                  : 0;
            const toward = pairTurn ? wrapAngle(Math.atan2(target.x - pos.x, target.z - pos.z) - yaw) : swing;
            const yawIn = turnFirst ? yaw + toward : yaw;
            let want = yawIn;
            let curve: ReturnType<typeof legCurve> = null;
            if (block.motion === "travel") {
                if (block.id === "clash" && face) want = Math.atan2(face.x - pos.x, face.z - pos.z);
                else if (flat > 0.03) {
                    // (A walk to meet its rival comes in facing it; a plunge goes straight down its line.)
                    // (A pair squares up on the spot at the end instead: its walk itself goes straight. A stay that keeps its
                    // homecoming heading comes home lined up with the way its next slot sets off, when that is roughly its
                    // way in: its last turn then is small.)
                    const homing = ctx.holds && step.to === "anchor" && ctx.nextYaw !== undefined && ctx.nextYaw !== null ? ctx.nextYaw : null;
                    curve = block.curve === "plunge" ? null : legCurve(world, block, pos, target, yawIn, face && !ctx.pair ? Math.atan2(face.x - target.x, face.z - target.z) : homing, face && !ctx.pair ? Math.PI / 2 : Math.PI / 3);
                    const end = legAt(pos, curve?.c ?? null, curve?.c2 ?? null, target, 1);
                    want = Math.atan2(end.dx, end.dz);
                }
            } else if (step.face === "sun") want = sunYaw(ctx.hours) + Math.PI / 2;
            else if (face && step.face === "water") want = yawIn + Math.max(Math.min(wrapAngle(Math.atan2(face.x - pos.x, face.z - pos.z) - yawIn), WATCH_TURN), -WATCH_TURN);
            else if (face) want = Math.atan2(face.x - pos.x, face.z - pos.z);
            // (On its own, a leg takes at least as long as its turn needs at its turn rate: a short hop round is not a spin.)
            const turning = block.motion === "travel" && !ctx.pair && flat > 0.03 ? (Math.abs(legTurn(pos, curve?.c ?? null, curve?.c2 ?? null, target, 1, yawIn)) * 1.2) / rate : 0;
            // (On its own it goes the curve's length at its pace, however long that takes: a leg is never sped up past its
            // clip. A pair keeps the template's bounds, the same on both sides.)
            const curved = ctx.pair || !TIMED_BY_LENGTH.has(block.id) || flat <= 0.03 ? travelSeconds : legLength(pos, curve?.c ?? null, curve?.c2 ?? null, target) / speedOf(block, walk, height, owner.profile, length, step.fast);
            const bounded = step.s ? (ctx.pair ? Math.min(Math.max(curved, step.s[0]), step.s[1]) : Math.max(curved, step.s[0])) : curved;
            const seconds = block.motion === "travel" ? Math.max(bounded, 0.2, turning) : Math.max(draw, 0.3);
            // It stops while it still has time to get back at its own pace (a pair keeps the shared reserve: both sides stop together).
            const homeward = ctx.pair ? 0 : Math.hypot(ctx.anchor.x - target.x, ctx.anchor.y - target.y, ctx.anchor.z - target.z) / speedOf(goBlock(owner.profile, kit, world, target, ctx.anchor, length), pace(owner.profile, length), 0, owner.profile, length);
            if (t + turnFirst + seconds > ctx.t1 - Math.max(reserve, Math.min(homeward, 40))) return false;
            if (turnFirst) {
                keys.push({t0: t, t1: t + turnFirst, block: BLOCKS.turn, from: pos, to: pos, yawIn: yaw, yaw: yawIn, c: null, c2: null, endLen: 0, face: null, carry, catch: null, prey: null, wade: false, toBase: false});
                t += turnFirst;
            }
            let thisCatch: Key["catch"] = null;
            if (step.catch) {
                caught = random() < (step.p ?? 0.5);
                thisCatch = {kind: step.catch, ok: caught, at: target};
                if (caught) carry = {item: step.catch, at: step.carry ?? defaultCarry(owner.profile)};
            }
            if (step.pick) {
                carry = {item: step.pick, at: step.carry ?? defaultCarry(owner.profile), material: step.pick === "material" ? material : undefined};
            }
            const prey: Key["prey"] = step.catch === "fish" || step.catch === "shellfish" || step.to === "prey" ? {kind: step.catch ?? "fish", at: target} : step.catch === "insect" ? {kind: "insect", at: target} : null;
            const key: Key = {t0: t, t1: t + seconds, block, from: pos, to: target, yawIn, yaw: want, c: curve?.c ?? null, c2: curve?.c2 ?? null, endLen: 0, face, carry, catch: thisCatch, prey, wade: block.id === "wade", toBase: false};
            keys.push(key);
            // Where it is facing as the key ends (the pose's own heading then, so the next key turns on from it exactly).
            yaw = keyPose(world, key, key.t1, length, keys.length > 1 ? keys[keys.length - 2] : null).yaw;
            t += seconds;
            pos = target;
            if (block.motion === "travel") facingRival = false;
            // A pair's walk up to its rival ends squaring up on the spot, face to face, before what comes next (both sides
            // the same time, from the larger one's turn rate: one timeline).
            if (ctx.pair && face && block.motion === "travel" && block.id !== "clash") {
                const square = (Math.PI * 1.5) / Math.min(turnRate(Math.max(length, ctx.pair.otherLength)), TURN_SPOT);
                if (t + square <= ctx.t1 - reserve) {
                    const toward = Math.atan2(face.x - pos.x, face.z - pos.z);
                    keys.push({t0: t, t1: t + square, block: BLOCKS.turn, from: pos, to: pos, yawIn: yaw, yaw: toward, c: null, c2: null, endLen: 0, face, carry, catch: null, prey: null, wade: false, toBase: false});
                    yaw = keyPose(world, keys[keys.length - 1], t + square, length, key).yaw;
                    t += square;
                    facingRival = true;
                }
            }
            if (step.eat || step.drop) carry = null;
            if (budgeted && !ctx.pair) {
                // (The turning it is drawn with along the step's keys, not just where it ends up facing: a curve swings.)
                let turn = 0;
                for (let k = before.n; k < keys.length; k++) turn += keyTurning(world, keys[k], length, k > 0 ? keys[k - 1] : null);
                const recent = turns.reduce((sum, e) => (e.t > t - 20 ? sum + e.turn : sum), 0);
                // (And over any minute, with the turn it still needs to head home: never a full turn in a minute.)
                const minute = turns.reduce((sum, e) => (e.t > t - 60 ? sum + e.turn : sum), 0);
                const away = Math.hypot(ctx.anchor.x - pos.x, ctx.anchor.z - pos.z) > 0.3;
                const homeYaw = away ? Math.atan2(ctx.anchor.x - pos.x, ctx.anchor.z - pos.z) : yaw;
                // (Its way home as it would go from here: a turn on the spot and the curve's own turning, a detour round
                // the shore or a rock included.)
                const homeward = away ? homeTurning(world, owner.profile, kit, pos, yaw, ctx.anchor, length, ctx.holds ? ctx.nextYaw ?? null : null, tailHome) : 0;
                // (Within its slot's last minute, its last turn on the spot to the way it sets off counts too.)
                const last = ctx.nextYaw !== undefined && ctx.nextYaw !== null && ctx.slotEnd !== undefined && t > ctx.slotEnd - 63 ? Math.abs(wrapAngle(ctx.nextYaw - homeYaw)) : 0;
                // (Every step: one that turns nothing still carries its turn home into its slot's last minute.)
                if (recent + turn > TURN_BUDGET || minute + turn + homeward + last > MINUTE_BUDGET) {
                    keys.length = before.n;
                    t = before.t;
                    pos = before.pos;
                    yaw = before.yaw;
                    carry = before.carry;
                    caught = before.caught;
                    return false;
                }
                if (turn > 0.05) turns.push({t, turn});
            }
        }
        return true;
    };
    let completed = sequence(template.steps);
    if (completed && template.loop !== undefined) {
        for (let n = 0; n < 8 && completed; n++) {
            caught = false;
            completed = sequence(template.steps.slice(template.loop));
        }
    }
    if (template.tail) sequence(template.tail, false);
    if (!keys.length) return null;
    // The prey is there while it waits for it: a wait, a scan or a hover before a catch shows the school or swarm it watches.
    for (let i = keys.length - 2; i >= 0; i--) {
        const next = keys[i + 1].prey;
        if (next && !keys[i].prey && WATCHING.has(keys[i].block.id)) keys[i] = {...keys[i], prey: next};
    }
    // Back to its schedule's pose (where it began, for a stay; where its schedule has it by then, for a pair), its own way:
    // this last key goes to the live pose, so it never snaps. It ends inside the window (sped up if it must).
    // (A pair's schedule walks on while it fights: its way back goes straight to where that will have it by the end.)
    const estimate = ctx.homeAt ? Math.hypot(ctx.anchor.x - pos.x, ctx.anchor.z - pos.z) / Math.max(speedOf(BLOCKS.walk, pace(owner.profile, length), 0, owner.profile, length), 0.1) : 0;
    const home = ctx.homeAt ? ctx.homeAt(Math.min(t + Math.max(estimate, 0.6), ctx.t1 + 2)) : ctx.anchor;
    const away = Math.hypot(home.x - pos.x, home.y - pos.y, home.z - pos.z);
    // (Its template's own way home when it has one: a heron wades out of the shallows, it does not walk round them.)
    let back = tailHome && !ctx.homeAt ? tailHome : goBlock(owner.profile, kit, world, pos, home, length);
    // (A swimmer that flies flies back if it could not swim it in time.)
    if (back.id === "swim" && kit.flies(owner.profile) && away / speedOf(back, pace(owner.profile, length), 0, owner.profile, length) > Math.max(ctx.t1 + 2 - t, 0.6)) back = BLOCKS.fly;
    // Home well away from the way it faces: it turns on the spot first (when there is time), then a gentle arc home. A
    // stay that keeps its homecoming heading comes in along its way; anything else lines up with its schedule pose's
    // heading when that is roughly its way in (never a loop to line up).
    const homeFlat = Math.hypot(home.x - pos.x, home.z - pos.z);
    // (A pair's too: this is its last key, after both sides' shared timeline.)
    // (A shuffle home of a few centimetres, under SHUFFLE, keeps its heading: no turning round for a step.)
    const homeSwing = homeFlat > SHUFFLE && TURNS_FIRST.has(back.id) ? wrapAngle(Math.atan2(home.x - pos.x, home.z - pos.z) - yaw) : 0;
    const homeTurn = Math.abs(homeSwing) > (DRIFTS.has(back.id) ? DRIFT_TURN : TURN_FIRST) ? (Math.abs(homeSwing) * 1.5) / Math.min(turnRate(length), TURN_SPOT) : 0;
    if (homeTurn && t + homeTurn + 0.6 <= ctx.t1 + 2) {
        keys.push({t0: t, t1: t + homeTurn, block: BLOCKS.turn, from: pos, to: pos, yawIn: yaw, yaw: yaw + homeSwing, c: null, c2: null, endLen: 0, face: null, carry, catch: null, prey: null, wade: false, toBase: false});
        t += homeTurn;
        yaw += homeSwing;
    }
    const curve = legCurve(world, back, pos, home, yaw, ctx.holds ? ctx.nextYaw ?? null : ctx.homeAt ? (home as P & {yaw: number}).yaw : ctx.yaw0);
    const room = Math.max(ctx.t1 + 2 - t, 0.6);
    const turning = Math.hypot(home.x - pos.x, home.z - pos.z) > 0.03 ? (Math.abs(legTurn(pos, curve?.c ?? null, curve?.c2 ?? null, home, 1, yaw)) * 1.2) / turnRate(length) : 0;
    const along = ctx.pair || Math.hypot(home.x - pos.x, home.z - pos.z) <= 0.03 ? away : legLength(pos, curve?.c ?? null, curve?.c2 ?? null, home);
    // (A rival walks off home at the same stiff half walk it came up at.)
    const wanted = Math.max(along / (speedOf(back, pace(owner.profile, length), 0, owner.profile, length) * (ctx.pair && back.id === "walk" ? 0.5 : 1)), 0.6, ctx.pair ? 0 : turning);
    const seconds = Math.min(wanted, room);
    // (Its heading on the way: a stay that keeps its homecoming heading keeps the one it has, even with nowhere left to
    // go; anything else turns to its schedule pose's.)
    keys.push({t0: t, t1: t + seconds, block: back, from: pos, to: home, yawIn: yaw, yaw: ctx.holds ? (curve?.c2 && ctx.nextYaw !== undefined && ctx.nextYaw !== null ? ctx.nextYaw : yaw) : ctx.homeAt ? (home as P & {yaw: number}).yaw : ctx.yaw0, c: curve?.c ?? null, c2: null, endLen: curve?.len ?? 0, face: null, carry, catch: null, prey: null, wade: false, toBase: true, fixed: Boolean(ctx.homeAt)});
    t += seconds;
    return {id: ctx.seed, recipe: template.id, t0: ctx.t0, t1: t, keys, anchor: ctx.anchor, length, other: null, role: ctx.pair?.role ?? null};
}

/** The water it faces from a spot: the nearest way to its heading that has water (it turns as little as it can). */
function waterFace(world: ScheduleWorld, at: P, length: number, heading: number): P | null {
    const reach = Math.min(Math.max(length * 40, 4), 14);
    for (const off of [0, 0.35, -0.35, 0.7, -0.7, 1.1, -1.1, 1.6, -1.6, 2.1, -2.1, 2.6, -2.6, Math.PI]) {
        for (const f of [0.15, 0.35, 0.6, 1]) {
            const x = at.x + Math.sin(heading + off) * reach * f;
            const z = at.z + Math.cos(heading + off) * reach * f;
            if (world.sampler.heightAt(x, z) < -0.05) return {x, y: 0, z};
        }
    }
    return null;
}

function defaultCarry(profile: ArkBehaviourProfile): CarryAt {
    return profile.move === "fly" || profile.moves.includes("fly") ? "beak" : "mouth";
}

const WATCHING = new Set(["ambush", "scan", "freeze", "hover", "perch", "stalk"]);

/** Legs timed by their own length at their pace (not the fixed hops: a take-off, a landing, a leap, a slide in). */
const TIMED_BY_LENGTH = new Set(["walk", "run", "flee", "stalk", "wade", "crawl", "carry", "push", "climb", "swim", "dive", "surface", "fly"]);

// MARK: The pose

const ease = (u: number) => u * u * (3 - 2 * u);


/** Where a key puts it at a time, and its attitude. */
function keyPose(world: ScheduleWorld, key: Key, epoch: number, length: number, previous: Key | null, endYaw: number | null = null): {p: P; yaw: number; pitch: number; roll: number; u: number; aloft: boolean} {
    const span = Math.max(key.t1 - key.t0, 1e-3);
    const u = Math.min(Math.max((epoch - key.t0) / span, 0), 1);
    const b = key.block;
    const {from, to} = key;
    let x = from.x;
    let y = from.y;
    let z = from.z;
    const rate = turnRate(length);
    const elapsed = Math.max(epoch - key.t0, 0);
    let yaw = turned(key.yawIn, key.yaw, elapsed, rate);
    if (b.motion === "travel") {
        const flat = Math.hypot(to.x - from.x, to.z - from.z);
        // How far along the ground it is (each curve's own pace), and how high.
        let along: number;
        switch (b.curve) {
            case "plunge":
                // Steep and gathering speed: most of the drop in the last part.
                along = Math.min(u * 1.25, 1);
                y = from.y + (to.y - from.y) * Math.pow(u, 1.6);
                break;
            case "arc":
                along = ease(u);
                y = from.y + (to.y - from.y) * along + Math.min(flat * 0.25, 2.5) * 4 * u * (1 - u);
                break;
            case "leap":
                along = u;
                y = from.y + (to.y - from.y) * u + Math.max(length * 0.6, 0.12 + flat * 0.3) * 4 * u * (1 - u);
                break;
            case "rise":
                along = u;
                y = from.y + (to.y - from.y) * (1 - (1 - u) * (1 - u));
                break;
            case "dive":
                along = u;
                y = from.y + (to.y - from.y) * Math.min(ease(u) * 1.6, 1);
                break;
            case "ground":
                along = b.id === "clash" ? u * u : ease(u);
                break;
            default:
                along = ease(u);
                y = from.y + (to.y - from.y) * along;
        }
        // Along its curve (it leaves the way it was heading; the last leg comes in along its schedule pose's heading).
        const lineUp = key.toBase && key.c && key.endLen > 0 && endYaw !== null && Math.abs(wrapAngle(endYaw - Math.atan2(to.x - from.x, to.z - from.z))) < Math.PI / 3;
        const c2 = lineUp ? {x: to.x - Math.sin(endYaw!) * key.endLen, z: to.z - Math.cos(endYaw!) * key.endLen} : key.toBase ? null : key.c2;
        const at = legAt(from, key.c, c2, to, along);
        x = at.x;
        z = at.z;
        if (b.curve === "ground") {
            const h = world.sampler.heightAt(x, z);
            y = key.wade ? Math.min(h, 0.02) : b.wet && h < 0 ? h : Math.max(h, 0);
        }
        // It faces the way it goes (turning into it from its heading at its turn rate); a charge turns to its rival.
        if (!(b.id === "clash" && key.face) && flat > (key.toBase ? SHUFFLE : 0.03)) yaw = turnedBy(key.yawIn, legTurn(from, key.c, c2, to, along, key.yawIn), elapsed, rate);
    }
    // Its own small motion while it holds.
    // On the spot the body holds still: a dig, a peck, a sweep or a scrape is the head's and the clip's (`dig`), a dust
    // bath the roll's (its root shuffled back and forth twice a second, and read as jitter: a foraging meerkat's way
    // turned 33 times a minute). It only bobs (heave), and a strike lunges forward and goes on from there.
    const phase = (epoch - key.t0) * (b.rate ?? 1) * Math.PI * 2;
    const heave = (b.heave ?? 0) * length * (b.id === "bury" || b.id === "incubate" ? Math.min(u * 4, 1) : 0.5 + 0.5 * Math.sin(phase));
    if (b.motion === "hold") {
        if (b.id === "strike") {
            const k = ease(u);
            x = from.x + (to.x - from.x) * k;
            y = from.y + (to.y - from.y) * k;
            z = from.z + (to.z - from.z) * k;
        }
        y += heave;
    }
    const wave = Math.sin(phase);
    // The attitude eases in from the last block's over its first moment.
    const blend = previous ? ease(Math.min((epoch - key.t0) / 0.3, 1)) : 1;
    const pitchNow = (b.pitch ?? 0) + (b.pitchWave ?? 0) * wave;
    const pitchBefore = previous ? previous.block.pitch ?? 0 : 0;
    const pitch = pitchBefore + (pitchNow - pitchBefore) * blend;
    const roll = ((b.roll ?? 0) + (b.rollWave ?? 0) * wave) * blend + (previous ? (previous.block.roll ?? 0) * (1 - blend) : 0);
    const ground = Math.max(world.sampler.heightAt(x, z), 0);
    return {p: {x, y, z}, yaw, pitch, roll, u, aloft: Boolean(b.aloft) && y > ground + 0.05};
}

function actOf(episode: Episode, key: Key, index: number, at: ReturnType<typeof keyPose>): RecipeAct {
    const b = key.block;
    const states = b.states;
    // (The catch is in its mouth, bill or feet only from the moment it is made: until then the quarry is still loose.)
    const loose = Boolean(key.catch?.ok) && at.u < (b.motion === "hold" ? CATCH_AT_HOLD : 0.98);
    const fx = b.fx ? {kind: b.fx, at: b.fxAt === "end" ? key.to : b.fxAt === "during" ? at.p : key.from, id: `${episode.id}#${index}`, during: b.fxAt === "during", when: b.fxAt ?? "start"} : null;
    return {
        episode: episode.id,
        recipe: episode.recipe,
        block: b.id,
        state: states[Math.min(Math.floor(at.u * states.length), states.length - 1)],
        u: at.u,
        pitch: at.pitch,
        roll: at.roll,
        own: true,
        carry: loose ? null : key.carry,
        prey: key.prey,
        catch: key.catch,
        fx,
        mark: b.mark ? {kind: b.mark, at: key.from, id: `${episode.id}#${index}`, from: key.t0} : null,
        label: TEMPLATES[episode.recipe]?.label ?? episode.recipe,
        with: episode.other ?? null
    };
}

// MARK: The quarry (`recipe-hunt.ts`): the one ambient creature a hunt goes after

/** A hold's catch (a strike, a swipe, a scoop) is made this far through it: the lunge's reach. */
const CATCH_AT_HOLD = 0.7;
/** What leads up to a catch: it is watching its quarry through these (the quarry is there from the first of them). */
const LEAD_UP = new Set(["stalk", "freeze", "scan", "ambush", "hover", "perch", "run", "turn", "take_off", "wade", "swim", "dive", "fly"]);
const quarryMemo = new WeakMap<Episode, QuarryTrack[]>();
const NO_TRACKS: QuarryTrack[] = [];

/** Its pose inside an episode at a time (the keys only: catches are never in the last blend home). */
function episodeKeyPose(world: ScheduleWorld, episode: Episode, epoch: number) {
    const keys = episode.keys;
    let i = 0;
    while (i + 1 < keys.length && keys[i].t1 <= epoch) i++;
    return {key: keys[i], at: keyPose(world, keys[i], epoch, episode.length, i > 0 ? keys[i - 1] : null)};
}

/**
 * Where a catch is made at a time: its mouth or bill a little ahead of the body (half a length), a pounce's forepaws,
 * a diving bird's bill below it, an osprey's talons under it.
 */
function mouthOf(world: ScheduleWorld, episode: Episode, catchBlock: string, epoch: number) {
    const {at} = episodeKeyPose(world, episode, epoch);
    const length = episode.length;
    const reach = catchBlock === "dive_feet" ? 0 : catchBlock === "leap" ? length * 0.45 : catchBlock === "strike" ? length * 0.6 : length * 0.5;
    const c = Math.cos(Math.min(Math.abs(at.pitch), 1.4));
    const y = catchBlock === "dive_air" ? at.p.y - length * 0.35 : catchBlock === "dive_feet" ? at.p.y : at.p.y + heightOf(length) * 0.5;
    return {x: at.p.x + Math.sin(at.yaw) * reach * c, y, z: at.p.z + Math.cos(at.yaw) * reach * c, yaw: at.yaw};
}

/**
 * The quarry of each catch in an episode (fish and insects: a worm comes out of the ground in the bill, a shellfish
 * off the bottom, and are drawn as carried). Built once per episode, pure in its keys.
 */
export function quarriesOf(world: ScheduleWorld, episode: Episode): QuarryTrack[] {
    const memo = quarryMemo.get(episode);
    if (memo) return memo;
    const out: QuarryTrack[] = [];
    const keys = episode.keys;
    keys.forEach((key, i) => {
        const c = key.catch;
        if (!c || (c.kind !== "fish" && c.kind !== "insect")) return;
        const b = key.block.id;
        const look: QuarryLook = c.kind === "fish" ? "fish" : key.block.aloft && b !== "leap" ? "flier" : "hopper";
        const hold = key.block.motion === "hold";
        const tc = hold ? key.t0 + (key.t1 - key.t0) * CATCH_AT_HOLD : key.t1 - 0.02;
        // Seen from the first of the watching that leads up to it (a stalk, a freeze, an ambush, a hover), at most 14 s.
        let h = i;
        while (h > 0 && LEAD_UP.has(keys[h - 1].block.id) && !keys[h - 1].catch && tc - keys[h - 1].t0 < 14) h--;
        const tv = keys[h].t0;
        const prev = keys[i - 1];
        let ts: number;
        if (b === "leap") ts = prev?.block.id === "run" ? prev.t0 + 0.15 : key.t0 + (key.t1 - key.t0) * 0.3;
        else if (hold && prev && (prev.block.id === "swim" || prev.block.id === "dive") && prev.prey) ts = prev.t0 + (prev.t1 - prev.t0) * 0.3;
        else if (hold) ts = key.t0 - 0.05;
        else if (b === "dive_air" || b === "dive_feet") ts = tc - 0.32;
        else if (b === "fly") ts = Math.max(key.t0 + (key.t1 - key.t0) * 0.35, tc - 1.2);
        else ts = key.t0 + (key.t1 - key.t0) * 0.25;
        // A watcher's fish swims in to it while it waits (a heron in ambush, a bear at the river, a pelican).
        const approach = hold && ts >= key.t0 - 0.1 && (prev?.block.id === "ambush" || prev?.block.id === "scan");
        out.push(
            buildQuarry({
                id: `${episode.id}#${i}`,
                kind: c.kind,
                look,
                ok: c.ok,
                tv: Math.max(tv, ts - 14),
                ts,
                tc,
                mouth: (t) => mouthOf(world, episode, b, t),
                length: episode.length,
                heightAt: (x, z) => world.sampler.heightAt(x, z),
                approach
            })
        );
    });
    quarryMemo.set(episode, out);
    return out;
}

/** The quarry it is after at a time, if any (cheap when none of its catches is near in time). */
function quarryNow(world: ScheduleWorld, episode: Episode, epoch: number): QuarryNow | null {
    let near = false;
    for (const k of episode.keys) if (k.catch && epoch >= k.t0 - 16 && epoch < k.t1 + 3) near = true;
    if (!near) return null;
    const tracks = quarriesOf(world, episode);
    if (tracks === NO_TRACKS) return null;
    for (const track of tracks) {
        if (epoch < track.tv || epoch >= track.te) continue;
        const now = quarryAt(track, epoch, (x, z) => world.sampler.heightAt(x, z));
        if (now) return now;
    }
    return null;
}

/** An episode's pose at a time over its schedule pose: it starts from it and ends back in it (the last moment blends). */
function onEpisode(world: ScheduleWorld, episode: Episode, base: TripPose, epoch: number): RecipePose {
    const keys = episode.keys;
    let i = 0;
    while (i + 1 < keys.length && keys[i].t1 <= epoch) i++;
    const key = keys[i];
    const live = key.toBase && !key.fixed ? {...key, to: {x: base.x, y: base.y, z: base.z}} : key;
    const holds = episode.endYaw !== undefined && episode.endYaw !== null;
    const drawn = keyPose(world, live, epoch, episode.length, i > 0 ? keys[i - 1] : null, key.toBase ? (holds || key.fixed ? keys[keys.length - 1].yaw : base.yaw) : null);
    // (A stay that keeps its heading heads for its fixed place, where its homecoming heading was worked out: its
    // schedule pose bobbing on the water only moves it, never swings it round.)
    const at = key.toBase && holds ? {...drawn, yaw: keyPose(world, key, epoch, episode.length, i > 0 ? keys[i - 1] : null, keys[keys.length - 1].yaw).yaw} : drawn;
    // Into its schedule's pose over the last 0.6 s (that is where it ends).
    const out = Math.min(Math.max((epoch - (episode.t1 - 0.6)) / 0.6, 0), 1);
    const k = ease(out);
    const x = at.p.x + (base.x - at.p.x) * k;
    const y = at.p.y + (base.y - at.p.y) * k;
    const z = at.p.z + (base.z - at.p.z) * k;
    // Its heading into its schedule pose's at its turn rate (its last leg mostly arrives along it already).
    const dyaw = wrapAngle(base.yaw - at.yaw);
    // (Only on its way back to it: never while it still runs its own way, a rival's run off or a chase.)
    const turnSeconds = Math.min(Math.max((Math.abs(dyaw) * 1.5) / turnRate(episode.length), 0.6), 3);
    const blendFrom = Math.min(Math.max(episode.t1 - turnSeconds, keys[keys.length - 1].t0), episode.t1 - 0.3);
    const kYaw = holds ? 0 : ease(Math.min(Math.max((epoch - blendFrom) / Math.max(episode.t1 - blendFrom, 1e-3), 0), 1));
    const act = actOf(episode, key, i, at);
    const quarry = quarryNow(world, episode, epoch);
    if (quarry) act.quarry = quarry;
    const moving = key.block.motion === "travel" && at.u < 1;
    return {...base, x, y, z, yaw: at.yaw + dyaw * kYaw, moving, aloft: at.aloft && k < 0.5, beat: key.block.beat, act: {...act, pitch: act.pitch * (1 - k), roll: act.roll * (1 - k)}};
}

// MARK: Which episode a trip is in

const HERE_DOINGS = new Set(["rest", "groom", "perch", "bask", "watch", "idle"]);

function stayEpisode(world: ScheduleWorld, trip: Trip, owner: TripOwner, kit: ScheduleKit): Episode | null {
    if (stayEpisodes.has(trip)) return stayEpisodes.get(trip)!;
    const species = speciesRecipes(owner.slug);
    let episode: Episode | null = null;
    const recipe = (trip as Trip & {recipe?: string | null}).recipe ?? null;
    const anchor = {x: trip.to.x, y: trip.to.y, z: trip.to.z};
    const hours = owner.hoursAt(trip.arrive);
    if (recipe && TEMPLATES[recipe]) {
        // It comes back a while before its slot ends: its homecoming and its schedule's setting off are two turns kept
        // apart, and the last seconds are for turning on the spot to the way it sets off. (A recipe's stay has no steps of
        // its own: its schedule pose holds still there, so it can keep its own heading.)
        const holds = !trip.stay.length;
        const t0 = trip.arrive + 0.5;
        const t1 = trip.end - (trip.end - trip.arrive >= 40 ? 10 : holds ? 5.5 : 2.5);
        if (t1 - t0 > 6) {
            const yaw0 = kit.basePose(world, trip, t0).yaw;
            const next = holds ? kit.tripAt(world, owner.profile, owner.animal, trip.end + 0.01, owner.hoursAt, owner.activity) : null;
            const nextYaw = next && next.slot !== trip.slot ? departureYaw(world, next, kit) : null;
            const built = buildEpisode({world, kit, owner, species, template: TEMPLATES[recipe], anchor, t0, t1, seed: `${owner.animal.id}#ep#${trip.slot}#${recipe}`, hours, yaw0, holds, nextYaw, slotEnd: trip.end});
            if (built && holds) {
                const last = built.keys[built.keys.length - 1];
                const end = keyPose(world, last, last.t1, built.length, built.keys[built.keys.length - 2] ?? null, last.yaw);
                episode = {...built, endYaw: end.yaw, nextYaw};
            } else episode = built;
        }
    } else if (HERE_DOINGS.has(trip.doing) && trip.end - trip.arrive > 14 && (!trip.stay.length || trip.stay.every((b, i, all) => i === 0 || (b.x === all[0].x && b.z === all[0].z)))) {
        // A stay where it already is: groom, stretch, call, bask in its posture, dry its wings.
        const random = rng(hashString(`${owner.animal.id}#here#${trip.slot}`));
        for (const {id, weight} of species.recipes) {
            const template = TEMPLATES[id];
            if (!template || template.kind !== "stay" || template.goal !== "here") continue;
            if (!template.replaces.includes(trip.doing) || !hourOk(template, hours)) continue;
            if (random() >= weight * 0.6 * seasonFactor(species, template.season, trip.arrive)) continue;
            const start = trip.arrive + 1 + random() * Math.max(trip.end - trip.arrive - 40, 0);
            episode = buildEpisode({world, kit, owner, species, template, anchor, t0: start, t1: Math.min(trip.end - 3, start + 60), seed: `${owner.animal.id}#here#${trip.slot}#${id}`, hours, yaw0: kit.basePose(world, trip, start).yaw});
            if (episode) break;
        }
    }
    stayEpisodes.set(trip, episode);
    return episode;
}

// MARK: Pairs

type PairLink = {template: string; other: ScheduleAnimal; otherProfile: ArkBehaviourProfile; otherSlug: string; otherActivity: ArkBehaviourProfile["activity"] | null | undefined; role: "a" | "b"; key: string};
const links = new WeakMap<ScheduleAnimal, PairLink[]>();

/** How often a pair may meet (world seconds), in season; and the longest a pair episode can run. */
export const PAIR_PERIOD = 600;
const PAIR_MAX = 90;

export type WireInput = {animal: ScheduleAnimal; profile: ArkBehaviourProfile; slug: string; activity?: ArkBehaviourProfile["activity"] | null};

/**
 * After a snapshot: who meets whom. Rival males of a species with a contest pair off with the nearest other male
 * (within 45 m, each in one pair); a male with a courtship display with the nearest female; two of a group that
 * groom each other by rank. Deterministic from ids and homes.
 */
export function wireRecipes(animals: WireInput[]) {
    const bySpecies = new Map<string, WireInput[]>();
    for (const a of animals) {
        links.delete(a.animal);
        const list = bySpecies.get(a.slug) ?? [];
        list.push(a);
        bySpecies.set(a.slug, list);
    }
    pairEpisodes.clear();
    const link = (a: WireInput, b: WireInput, template: string) => {
        const key = a.animal.id < b.animal.id ? `${template}#${a.animal.id}#${b.animal.id}` : `${template}#${b.animal.id}#${a.animal.id}`;
        // Role "a": the male in a courtship; the dominant (then the id) in a contest.
        const aIsMale = sexLook(a.animal.id, a.slug).sex === "male";
        const roleA: "a" | "b" = TEMPLATES[template].sex === "mixed" ? (aIsMale ? "a" : "b") : (a.profile.dominance ?? 0) * 1000 + unit(`${a.animal.id}#rank`) >= (b.profile.dominance ?? 0) * 1000 + unit(`${b.animal.id}#rank`) ? "a" : "b";
        const add = (x: WireInput, y: WireInput, role: "a" | "b") => {
            const list = links.get(x.animal) ?? [];
            list.push({template, other: y.animal, otherProfile: y.profile, otherSlug: y.slug, otherActivity: y.activity, role, key});
            links.set(x.animal, list);
        };
        add(a, b, roleA);
        add(b, a, roleA === "a" ? "b" : "a");
    };
    for (const [slug, list] of Array.from(bySpecies)) {
        const species = speciesRecipes(slug);
        const pairs = species.recipes.map((r) => TEMPLATES[r.id]).filter((t): t is Template => Boolean(t && t.kind === "pair" && t.id !== "mixed_follow"));
        if (!pairs.length || list.length < 2) continue;
        const sorted = [...list].sort((a, b) => a.animal.id.localeCompare(b.animal.id));
        const dist = (a: WireInput, b: WireInput) => Math.hypot(a.animal.home.x - b.animal.home.x, a.animal.home.z - b.animal.home.z);
        for (const template of pairs) {
            const taken = new Set<string>();
            const pool = template.sex === "males" ? sorted.filter((a) => sexLook(a.animal.id, slug).sex === "male") : sorted;
            if (template.id === "allogroom") {
                // Neighbours in rank within one group.
                const groups = new Map<string, WireInput[]>();
                for (const a of pool) {
                    const lead = a.animal.group?.leader.id ?? a.animal.id;
                    const g = groups.get(lead) ?? [];
                    g.push(a);
                    groups.set(lead, g);
                }
                for (const g of Array.from(groups.values())) {
                    const ranked = [...g].sort((a, b) => (a.animal.group?.rank ?? 0) - (b.animal.group?.rank ?? 0) || a.animal.id.localeCompare(b.animal.id));
                    for (let k = 0; k + 1 < ranked.length; k += 2) link(ranked[k], ranked[k + 1], template.id);
                }
                continue;
            }
            for (const a of pool) {
                if (taken.has(a.animal.id)) continue;
                if (template.sex === "mixed" && sexLook(a.animal.id, slug).sex !== "male") continue;
                const candidates = pool.filter((b) => b !== a && !taken.has(b.animal.id) && (template.sex !== "mixed" || sexLook(b.animal.id, slug).sex === "female") && dist(a, b) < 45);
                if (!candidates.length) continue;
                const b = candidates.sort((m, n) => dist(a, m) - dist(a, n) || m.animal.id.localeCompare(n.animal.id))[0];
                taken.add(a.animal.id);
                taken.add(b.animal.id);
                link(a, b, template.id);
            }
        }
    }
    wireMixed(animals);
}

export function pairLinksOf(animal: ScheduleAnimal): ReadonlyArray<Pick<PairLink, "template" | "role" | "key"> & {other: string}> {
    return (links.get(animal) ?? []).map((l) => ({template: l.template, role: l.role, key: l.key, other: l.other.id}));
}

/** A pair's meeting windows (world seconds) between two times: in season every period, out of it one in four (pure). */
export function pairWindows(animal: ScheduleAnimal, slug: string, from: number, to: number): Array<{template: string; start: number; end: number; other: string}> {
    const out: Array<{template: string; start: number; end: number; other: string}> = [];
    const species = speciesRecipes(slug);
    for (const l of links.get(animal) ?? []) {
        const template = TEMPLATES[l.template];
        for (let period = Math.floor(from / PAIR_PERIOD); period * PAIR_PERIOD < to; period++) {
            const factor = seasonFactor(species, template.season, period * PAIR_PERIOD);
            if (!factor || (factor < 1 && hashString(`${l.key}#on#${period}`) % 4 !== 0)) continue;
            const start = period * PAIR_PERIOD + (hashString(`${l.key}#${period}`) % (PAIR_PERIOD - PAIR_MAX));
            if (start + PAIR_MAX >= from && start < to) out.push({template: l.template, start, end: start + PAIR_MAX, other: l.other.id});
        }
    }
    return out.sort((a, b) => a.start - b.start);
}

/** A pair's episode for one side at a time (null: none now). Both sides work out the same window from the pair's key. */
function pairEpisode(world: ScheduleWorld, owner: TripOwner, kit: ScheduleKit, epoch: number): Episode | null {
    const list = links.get(owner.animal);
    if (!list) return null;
    for (const l of list) {
        if (l.template === "mixed_follow") continue;
        const template = TEMPLATES[l.template];
        const species = speciesRecipes(owner.slug);
        const factor = seasonFactor(species, template.season, epoch);
        if (!factor) continue;
        // Out of a stored season, a quarter as often: one period in four.
        const period = Math.floor(epoch / PAIR_PERIOD);
        if (factor < 1 && hashString(`${l.key}#on#${period}`) % 4 !== 0) continue;
        const start = period * PAIR_PERIOD + (hashString(`${l.key}#${period}`) % (PAIR_PERIOD - PAIR_MAX));
        if (epoch < start || epoch >= start + PAIR_MAX) continue;
        const memoKey = `${l.key}#${period}#${l.role}`;
        let episode = pairEpisodes.get(memoKey);
        if (episode === undefined) {
            episode = null;
            const hours = owner.hoursAt(start);
            const own = kit.basePose(world, kit.tripAt(world, owner.profile, owner.animal, start, owner.hoursAt, owner.activity), start);
            const other = kit.basePose(world, kit.tripAt(world, l.otherProfile, l.other, start, owner.hoursAt, l.otherActivity), start);
            const ownTrip = kit.tripAt(world, owner.profile, owner.animal, start, owner.hoursAt, owner.activity);
            const otherTrip = kit.tripAt(world, l.otherProfile, l.other, start, owner.hoursAt, l.otherActivity);
            const onLand = (p: TripPose) => !p.aloft && world.sampler.heightAt(p.x, p.z) > 0.03 && p.y < Math.max(world.sampler.heightAt(p.x, p.z), 0) + 0.3;
            const awake = (t: Trip) => t.doing !== "sleep" && t.doing !== "to_roost";
            if (hourOk(template, hours) && onLand(own) && onLand(other) && awake(ownTrip) && awake(otherTrip) && Math.hypot(own.x - other.x, own.z - other.z) < 40) {
                episode = buildEpisode({
                    world,
                    kit,
                    owner,
                    species,
                    template,
                    anchor: {x: own.x, y: own.y, z: own.z},
                    t0: start,
                    t1: start + PAIR_MAX,
                    seed: `${l.key}#${period}`,
                    pair: {other: {x: other.x, y: other.y, z: other.z}, role: l.role, otherLength: l.other.length, pace: Math.min(pace(owner.profile, owner.animal.length), pace(l.otherProfile, l.other.length))},
                    hours,
                    yaw0: own.yaw,
                    homeAt: (at: number) => {
                        const p = kit.basePose(world, kit.tripAt(world, owner.profile, owner.animal, at, owner.hoursAt, owner.activity), at);
                        return {x: p.x, y: p.y, z: p.z, yaw: p.yaw};
                    }
                });
                if (episode) episode = {...episode, other: l.other.id, role: l.role};
            }
            pairEpisodes.set(memoKey, episode);
            if (pairEpisodes.size > 400) pairEpisodes.delete(pairEpisodes.keys().next().value as string);
        }
        if (episode && epoch < episode.t1) return episode;
    }
    return null;
}

// MARK: Flocks: murmurations at dusk, V-formations in the air

/** The murmuration's window (island hours) and how many ambient flockmates fill it out near the camera. */
export const MURMURATION_HOURS: [number, number] = [17.45, 18.25];
export const MURMURATION_AMBIENT = 1400;

/**
 * A point of a murmuration (pure in its centre, the time and the bird's index): a shape that stretches, turns and
 * drifts over the roost, each bird circling inside it, with density waves passing through. Catalogue birds use
 * their own index; the scene's ambient flockmates use the rest.
 */
export function murmurationPoint(centre: P, seed: number, index: number, epoch: number): {x: number; y: number; z: number} {
    const t = epoch;
    const s = (seed % 1000) / 1000;
    const cx = centre.x + 9 * Math.sin(t * 0.031 + s * 6) + 4 * Math.sin(t * 0.083 + s * 2);
    const cz = centre.z + 7 * Math.cos(t * 0.027 + s * 5) + 3 * Math.cos(t * 0.071 + s);
    // Over the treetops (the island's crowns reach 15–20 m).
    const cy = centre.y + 25 + 4 * Math.sin(t * 0.05 + s * 3);
    const a = 13 + 6 * Math.sin(t * 0.07 + s);
    const b = 4.5 + 2.2 * Math.sin(t * 0.11 + 1 + s);
    const c = 8 + 5 * Math.cos(t * 0.053 + s * 4);
    const turn = 0.35 * t * 0.02 + Math.sin(t * 0.013 + s) * 1.2;
    // The bird's seeded place in a unit ball, circling about a slowly wandering axis.
    const r = rng(hashString(`m${seed}#${index}`));
    const u0 = r() * 2 - 1;
    const th = r() * Math.PI * 2;
    const rad = Math.cbrt(r());
    const q = Math.sqrt(1 - u0 * u0);
    const bx = rad * q * Math.cos(th);
    const by = rad * u0;
    const bz = rad * q * Math.sin(th);
    const spin = (0.22 + 0.12 * r()) * t;
    const rx = bx * Math.cos(spin) - bz * Math.sin(spin);
    const rz = bx * Math.sin(spin) + bz * Math.cos(spin);
    const wave = 0.18 * Math.sin(rx * 4 - t * 1.7) + 0.08 * Math.sin(rz * 6 + t * 1.1);
    const lx = (rx + wave) * a;
    const ly = by * b + 1.5 * Math.sin(rx * 3 + t * 0.9);
    const lz = rz * c;
    return {x: cx + lx * Math.cos(turn) - lz * Math.sin(turn), y: Math.max(cy + ly, centre.y + 4), z: cz + lx * Math.sin(turn) + lz * Math.cos(turn)};
}

/** Its murmuration now: its flock's roost and the time inside the window, or null. */
export function murmurationOf(world: ScheduleWorld, owner: TripOwner, kit: ScheduleKit, epoch: number): {centre: P; seed: number; t0: number; t1: number} | null {
    const species = speciesRecipes(owner.slug);
    if (!species.has.has("murmuration")) return null;
    const hours = owner.hoursAt(epoch);
    if (hours < MURMURATION_HOURS[0] || hours > MURMURATION_HOURS[1]) return null;
    const leader = owner.animal.group?.leader ?? owner.animal;
    const leaderProfile = owner.animal.group?.profile ?? owner.profile;
    const roost = kit.roostOf(world, leaderProfile, leader);
    // The window in world seconds (the hours map to the clock one to one).
    const t0 = epoch - (hours - MURMURATION_HOURS[0]) * 3600;
    const t1 = t0 + (MURMURATION_HOURS[1] - MURMURATION_HOURS[0]) * 3600;
    return {centre: {x: roost.x, y: Math.max(world.sampler.heightAt(roost.x, roost.z), 0), z: roost.z}, seed: hashString(leader.id), t0, t1};
}

/**
 * A small animal at its microhabitat (off the schedule: house starlings) in its flock's murmuration at dusk: the
 * flock is everyone of its species round the same spot (a 40 m cell), over that spot. Pure in (its place, the time).
 */
export function microMurmuration(id: string, slug: string, at: {x: number; y: number; z: number}, epoch: number, hours: number, heightAt: (x: number, z: number) => number): (P & {yaw: number; pitch: number; roll: number; act: RecipeAct}) | null {
    if (!enabled || !speciesRecipes(slug).has.has("murmuration")) return null;
    if (hours < MURMURATION_HOURS[0] || hours > MURMURATION_HOURS[1]) return null;
    const cx = (Math.floor(at.x / 40) + 0.5) * 40;
    const cz = (Math.floor(at.z / 40) + 0.5) * 40;
    const centre = {x: cx, y: Math.max(heightAt(cx, cz), 0), z: cz};
    const seed = hashString(`${slug}#${cx}#${cz}`);
    const t0 = epoch - (hours - MURMURATION_HOURS[0]) * 3600;
    const t1 = t0 + (MURMURATION_HOURS[1] - MURMURATION_HOURS[0]) * 3600;
    const index = hashString(id) % 997;
    const p = murmurationPoint(centre, seed, index, epoch);
    const ahead = murmurationPoint(centre, seed, index, epoch + 0.2);
    const k = ease(Math.min(Math.min(epoch - t0, t1 - epoch) / 40, 1));
    const climb = Math.atan2(ahead.y - p.y, Math.hypot(ahead.x - p.x, ahead.z - p.z) || 1e-3);
    const act: RecipeAct = {episode: `murmuration#${seed}#${Math.floor(t0)}`, recipe: "murmuration", block: "fly", state: "fly", u: (epoch - t0) / (t1 - t0), pitch: -climb * k, roll: -0.4 * k * Math.sin(epoch * 0.9 + index), own: true, carry: null, prey: null, catch: null, fx: null, mark: null, label: TEMPLATES.murmuration.label, flock: {centre, seed, t0, t1}};
    return {x: at.x + (p.x - at.x) * k, y: at.y + (p.y - at.y) * k, z: at.z + (p.z - at.z) * k, yaw: Math.atan2(ahead.x - p.x, ahead.z - p.z), pitch: act.pitch, roll: act.roll, act};
}

function murmurationPose(world: ScheduleWorld, owner: TripOwner, kit: ScheduleKit, base: TripPose, epoch: number): RecipePose | null {
    const m = murmurationOf(world, owner, kit, epoch);
    if (!m) return null;
    const index = hashString(owner.animal.id) % 997;
    const p = murmurationPoint(m.centre, m.seed, index, epoch);
    const ahead = murmurationPoint(m.centre, m.seed, index, epoch + 0.2);
    // Up into it from where it was over the first 40 s, down to its roost over the last 40 s.
    const k = ease(Math.min(Math.min(epoch - m.t0, m.t1 - epoch) / 40, 1));
    const x = base.x + (p.x - base.x) * k;
    const y = base.y + (p.y - base.y) * k;
    const z = base.z + (p.z - base.z) * k;
    const yaw = Math.atan2(ahead.x - p.x, ahead.z - p.z);
    const climb = Math.atan2(ahead.y - p.y, Math.hypot(ahead.x - p.x, ahead.z - p.z) || 1e-3);
    return {
        ...base,
        x,
        y,
        z,
        // (Its heading eases round with the climb into the flock and the drop out of it: no switch half way.)
        yaw: base.yaw + wrapAngle(yaw - base.yaw) * k,
        moving: true,
        aloft: true,
        beat: "fly",
        act: {episode: `murmuration#${m.seed}#${Math.floor(m.t0)}`, recipe: "murmuration", block: "fly", state: "fly", u: (epoch - m.t0) / (m.t1 - m.t0), pitch: -climb * k, roll: -0.4 * k * Math.sin(epoch * 0.9 + index), own: true, carry: null, prey: null, catch: null, fx: null, mark: null, label: TEMPLATES.murmuration.label, flock: m}
    };
}

/** A flock follower in the air takes its V slot behind its leader (geese, cranes), easing in and out of it. */
function formationPose(world: ScheduleWorld, owner: TripOwner, trip: Trip, base: TripPose, epoch: number, kit: ScheduleKit): RecipePose | null {
    const group = owner.animal.group;
    if (!group || !trip.shadow || !base.aloft) return null;
    const species = speciesRecipes(owner.slug);
    if (!species.has.has("v_formation")) return null;
    const lead = trip.shadow.trips.find((t) => epoch >= t.start && epoch < t.end) ?? trip.shadow.trips[trip.shadow.trips.length - 1];
    const leader = kit.basePose(world, lead, Math.min(epoch, lead.end - 0.001));
    if (!leader.aloft) return null;
    const rank = Math.max(group.rank, 1);
    const side = rank % 2 ? 1 : -1;
    const k = Math.ceil(rank / 2);
    const spacing = Math.max(owner.animal.length, 0.3) * 1.5;
    const fx = Math.sin(leader.yaw);
    const fz = Math.cos(leader.yaw);
    const tx = leader.x - fx * k * spacing * 0.95 + fz * side * k * spacing * 0.7;
    const tz = leader.z - fz * k * spacing * 0.95 - fx * side * k * spacing * 0.7;
    const ty = leader.y + k * 0.04 * spacing;
    // Into the V over 8 s after it joins, out of it over the last 8 s of the slot.
    const w = ease(Math.min(Math.max(Math.min(epoch - trip.start - 6, trip.end - epoch) / 8, 0), 1));
    return {...base, x: base.x + (tx - base.x) * w, y: base.y + (ty - base.y) * w, z: base.z + (tz - base.z) * w, yaw: base.yaw + Math.atan2(Math.sin(leader.yaw - base.yaw), Math.cos(leader.yaw - base.yaw)) * w};
}

// MARK: Land and water crossings

function crossingPose(world: ScheduleWorld, owner: TripOwner, trip: Trip, base: TripPose, epoch: number): RecipePose | null {
    if (base.beat !== "enter_water" && base.beat !== "exit_water" && base.beat !== "shake") return null;
    const species = speciesRecipes(owner.slug);
    const length = Math.max(owner.animal.length, 0.05);
    // The leg it is on (or, for the shake after climbing out, the time since it arrived).
    let t = epoch - trip.start;
    let leg = trip.legs[0];
    for (const l of trip.legs) {
        leg = l;
        if (t < l.seconds) break;
        t -= l.seconds;
    }
    const u = Math.min(Math.max(t / Math.max(leg.seconds, 1e-3), 0), 1);
    if (base.beat === "shake") {
        const block = AFTER_BLOCKS[species.after];
        if (!block || block === "shake_off") return null;
        const b = BLOCKS[block];
        return {...base, beat: b.beat, act: {episode: `after#${trip.slot}`, recipe: "crossing", block: b.id, state: b.states[0], u: 0, pitch: b.pitch ?? 0, roll: b.roll ?? 0, own: false, carry: null, prey: null, catch: null, fx: null, mark: null, label: b.label}};
    }
    const blockId = base.beat === "enter_water" ? ENTRY_BLOCKS[species.entry] : EXIT_BLOCKS[species.exit];
    const b = BLOCKS[blockId];
    if (!b || blockId === "walk" || blockId === "wade") return null;
    let y = base.y;
    if (b.curve === "leap") y += Math.max(length * 0.5, 0.1) * 4 * u * (1 - u);
    if (b.id === "slide_in") y = Math.max(base.y - length * 0.15, Math.min(world.sampler.heightAt(base.x, base.z), base.y));
    if (b.id === "haul_out") y += (b.heave ?? 0) * length * Math.max(Math.sin(u * Math.PI * 6), 0);
    return {
        ...base,
        y,
        beat: b.beat,
        act: {episode: `cross#${trip.slot}`, recipe: "crossing", block: b.id, state: b.states[0], u, pitch: b.pitch ?? 0, roll: 0, own: false, carry: null, prey: null, catch: null, fx: b.fx ? {kind: b.fx, at: {x: base.x, y: 0, z: base.z}, id: `cross#${owner.animal.id}#${trip.slot}#${b.id}`, during: b.fxAt === "during", when: b.fxAt ?? "start"} : null, mark: null, label: b.label}
    };
}

// MARK: The schedule's other hook

/**
 * Its pose with its recipe laid over: a pair's meeting, its flock's murmuration, its V, a stay's episode, a
 * crossing's style, its sleeping posture. Pure in (the trip, the time): the same near and far.
 */
export function episodePose(world: ScheduleWorld, trip: Trip, base: TripPose, epoch: number, kit: ScheduleKit): RecipePose {
    if (!enabled) return base;
    const owner = (trip as Trip & {owner?: TripOwner | null}).owner;
    if (!owner) return base;
    const pose = settingOff(world, owner, trip, overlaid(world, owner, trip, base, epoch, kit), epoch, kit);
    // Ambient flock-mates round it (a swarm at its spot, its roost-mates streaming out at dusk), whatever it is doing.
    const flock = emergenceFlock(world, owner, kit, epoch) ?? (speciesRecipes(owner.slug).has.size ? swarmFlock(owner.animal.id, owner.slug, owner.animal.home, epoch, owner.hoursAt(epoch)) : null);
    return flock ? {...pose, flock} : pose;
}

function overlaid(world: ScheduleWorld, owner: TripOwner, trip: Trip, base: TripPose, epoch: number, kit: ScheduleKit): RecipePose {
    const murmuring = murmurationPose(world, owner, kit, base, epoch);
    if (murmuring) return murmuring;
    if (trip.doing === "sleep") return postureOf(owner, base);
    const pair = pairEpisode(world, owner, kit, epoch);
    if (pair) return onEpisode(world, pair, base, epoch);
    const mixed = mixedPose(world, owner, kit, base, epoch);
    if (mixed) return mixed;
    if (trip.shadow) return formationPose(world, owner, trip, base, epoch, kit) ?? base;
    if (epoch >= trip.arrive) {
        const stay = stayEpisode(world, trip, owner, kit);
        if (stay && epoch >= stay.t0 && epoch < stay.t1) return onEpisode(world, stay, base, epoch);
        // Home from it: it keeps the heading it came home with, and in the last seconds turns on the spot to the way its
        // next slot sets off (at behaviour's turn rate).
        if (stay && stay.endYaw !== undefined && stay.endYaw !== null && epoch >= stay.t1 && epoch < trip.end) {
            const toward = stay.nextYaw ?? stay.endYaw;
            const span = (Math.abs(wrapAngle(toward - stay.endYaw)) * 1.5) / TURN_SPOT;
            return {...base, yaw: turned(stay.endYaw, toward, epoch - (trip.end - span), TURN_SPOT)};
        }
        const hovering = airStay(world, owner, trip, base, epoch, kit);
        if (hovering) return hovering;
    }
    return crossingPose(world, owner, trip, base, epoch) ?? base;
}

/** How much its way home from here turns it (rad): a turn on the spot if it must, then the leg's curve, summed along it. */
function homeTurning(world: ScheduleWorld, profile: ArkBehaviourProfile, kit: ScheduleKit, from: P, yaw: number, home: P, length: number, endYaw: number | null = null, way: BlockDef | null = null): number {
    const block = way ?? goBlock(profile, kit, world, from, home, length);
    const chord = Math.atan2(home.x - from.x, home.z - from.z);
    const swing = wrapAngle(chord - yaw);
    const first = Math.abs(swing) > TURN_FIRST && TURNS_FIRST.has(block.id) ? Math.abs(swing) : 0;
    const start = first ? chord : yaw;
    const curve = legCurve(world, block, from, home, start, endYaw);
    let sum = first;
    let previous = start;
    for (let j = 1; j <= 12; j++) {
        const at = legAt(from, curve?.c ?? null, curve?.c2 ?? null, home, j / 12);
        if (Math.hypot(at.dx, at.dz) < 1e-6) continue;
        const a = Math.atan2(at.dx, at.dz);
        sum += Math.abs(wrapAngle(a - previous));
        previous = a;
    }
    return sum;
}

/** How much a key turns it as it is drawn (rad, its heading sampled along it). */
function keyTurning(world: ScheduleWorld, key: Key, length: number, previous: Key | null): number {
    const n = Math.min(Math.max(Math.ceil((key.t1 - key.t0) / 0.4), 3), 40);
    let last = keyPose(world, key, key.t0, length, previous).yaw;
    let sum = 0;
    for (let j = 1; j <= n; j++) {
        const yaw = keyPose(world, key, key.t0 + ((key.t1 - key.t0) * j) / n, length, previous).yaw;
        sum += Math.abs(wrapAngle(yaw - last));
        last = yaw;
    }
    return sum;
}

/** The way a slot sets off: its turn on the spot's heading if it starts with one, else its heading once it is on its way. */
function departureYaw(world: ScheduleWorld, trip: Trip, kit: ScheduleKit): number {
    const first = trip.legs[0];
    if (first && first.mode === "pause" && first.turn && first.yaw !== undefined) return first.yaw;
    return kit.basePose(world, trip, trip.start + 0.85).yaw;
}

/**
 * Setting off after a stay whose episode left it facing its own way: it has already turned on the spot to the way it
 * sets off (its stay's last seconds), so it keeps that through its schedule's own turn on the spot (or its first moment
 * on its way) and then follows its schedule pose. It never turns while it is already moving.
 */
function settingOff(world: ScheduleWorld, owner: TripOwner, trip: Trip, pose: RecipePose, epoch: number, kit: ScheduleKit): RecipePose {
    const since = epoch - trip.start;
    if (since < 0 || since >= 6) return pose;
    const before = kit.tripAt(world, owner.profile, owner.animal, trip.start - 0.01, owner.hoursAt, owner.activity);
    if (before === trip || before.end > trip.start + 0.01) return pose;
    const last = stayEpisode(world, before, (before as Trip & {owner?: TripOwner | null}).owner ?? owner, kit);
    if (!last || last.endYaw === undefined || last.endYaw === null) return pose;
    const facing = last.nextYaw ?? last.endYaw;
    const first = trip.legs[0];
    const hold = first && first.mode === "pause" && first.turn ? first.seconds : 0.85;
    if (since < hold) return {...pose, yaw: facing};
    return since - hold < 4 ? {...pose, yaw: turned(facing, pose.yaw, since - hold, TURN_SPOT)} : pose;
}

/** A flyer whose stay is a place in the air (a bat's beat, between its sallies) keeps flying there: a slow circle. */
function airStay(world: ScheduleWorld, owner: TripOwner, trip: Trip, base: TripPose, epoch: number, kit: ScheduleKit): RecipePose | null {
    if (trip.to.point !== null || !kit.flies(owner.profile)) return null;
    const ground = Math.max(world.sampler.heightAt(trip.to.x, trip.to.z), 0);
    if (trip.to.y < ground + 1.2) return null;
    const r = Math.max(owner.animal.length * 6, 1.2);
    const a = (epoch - trip.arrive) * (0.9 / r) * 2 + (hashString(owner.animal.id) % 628) / 100;
    // In from its arrival point over the first second.
    const k = ease(Math.min((epoch - trip.arrive) / 1.2, 1));
    const x = trip.to.x + (Math.cos(a) * r - Math.cos((hashString(owner.animal.id) % 628) / 100) * r) * k;
    const z = trip.to.z + (Math.sin(a) * r - Math.sin((hashString(owner.animal.id) % 628) / 100) * r) * k;
    return {...base, x, y: trip.to.y + 0.3 * Math.sin(a * 2), z, yaw: a + Math.PI, moving: true, aloft: true, beat: "fly", act: {episode: `air#${trip.slot}`, recipe: "air_stay", block: "fly", state: "fly", u: 0, pitch: 0, roll: -0.35, own: true, carry: null, prey: null, catch: null, fx: null, mark: null, label: "flying its beat"}};
}

const postureActs = new Map<string, RecipeAct>();

/** Its sleeping posture (one shared act per posture and attitude: sleeping animals are posed often). */
function postureOf(owner: TripOwner, base: TripPose): RecipePose {
    const posture = speciesRecipes(owner.slug).posture;
    if (!posture) return base;
    // A bat hangs head down from its feet (nose down a quarter turn about its feet on the limb); a sloth hangs level,
    // upside down (a half roll); an otter floats on its back.
    const flyer = owner.profile.move === "fly" || owner.profile.moves.includes("fly");
    const roll = (posture === "hang" && !flyer) || (posture === "float" && base.y <= 0.02) ? Math.PI : 0;
    const pitch = posture === "hang" && flyer ? Math.PI / 2 : posture === "curl" ? 0.15 : 0;
    const key = `${posture}#${roll}#${pitch}`;
    let act = postureActs.get(key);
    if (!act) postureActs.set(key, (act = Object.freeze({episode: "sleep", recipe: "posture", block: "sleep_pose", state: `sleep_${posture}`, u: 0, pitch, roll, own: false, carry: null, prey: null, catch: null, fx: null, mark: null, label: `sleeps (${posture.replace("_", " ")})`}) as RecipeAct));
    return {...base, act};
}

/** How long a dug hole, a mound or a hollow stays (world seconds), fading. */
export const MARK_SECONDS = 20 * 60;

export type RecipeMark = {id: string; kind: NonNullable<BlockDef["mark"]>; x: number; y: number; z: number; size: number; from: number; to: number};

/**
 * The marks an animal's recent episodes left (holes, mounds, hollows), still there at a time: pure in its trips, so
 * every viewer, and one who arrives late, sees the same ones. `trips` are its trips of the last `MARK_SECONDS`.
 */
export function marksOf(world: ScheduleWorld, trips: Trip[], epoch: number, kit: ScheduleKit): RecipeMark[] {
    const out: RecipeMark[] = [];
    for (const trip of trips) {
        const owner = (trip as Trip & {owner?: TripOwner | null}).owner;
        if (!owner || trip.end < epoch - MARK_SECONDS) continue;
        const episode = stayEpisode(world, trip, owner, kit);
        if (!episode) continue;
        for (let i = 0; i < episode.keys.length; i++) {
            const key = episode.keys[i];
            if (!key.block.mark || key.t0 > epoch) continue;
            // A burrow's spoil heap and a dust bath's hollow; a turtle's covered pit is a mound.
            const kind = episode.recipe === "dig_burrow" || (episode.recipe === "beach_nest" && i > 2) ? "mound" : key.block.mark;
            out.push({id: `${episode.id}#${i}`, kind, x: key.from.x, y: key.from.y, z: key.from.z, size: Math.max(episode.length * (kind === "hollow" ? 0.9 : 0.5), 0.06), from: key.t0, to: key.t0 + MARK_SECONDS});
        }
    }
    return out;
}

/** For the tests and the review: a stay's episode for a trip (null: none). */
export function episodeOfTrip(world: ScheduleWorld, trip: Trip, kit: ScheduleKit): Episode | null {
    const owner = (trip as Trip & {owner?: TripOwner | null}).owner;
    if (!owner) return null;
    return stayEpisode(world, trip, owner, kit);
}

/** The beat an act reads as (for code that only knows beats). */
export function beatOfAct(act: RecipeAct | null | undefined): ArkBeat | null {
    return act ? BLOCKS[act.block]?.beat ?? null : null;
}

// MARK: Round 2: swarms, bats, mixed flocks, molehills, coats, the duller sex, hangers

/** Hangers (bats, sloths: their posture is "hang"): the roost tags under limbs first (`canopy_hang`), then their own. */
export function recipeRoostTags(profile: ArkBehaviourProfile): AttachTag[] | null {
    if (!enabled || speciesRecipes(profile.slug).posture !== "hang") return null;
    return profile.move === "fly" || profile.moves.includes("fly") ? ["canopy_hang", "cave_mouth", "branch"] : ["canopy_hang", "branch"];
}

/** A swarm or a cluster round a spot now (pure in its spot and the time; its hours from its template), or null. */
export function swarmFlock(id: string, slug: string, at: P, epoch: number, hours: number): Flock | null {
    if (!enabled) return null;
    const species = speciesRecipes(slug);
    for (const kind of ["swarm", "swarm_dusk", "cluster"] as const) {
        if (!species.has.has(kind)) continue;
        const template = TEMPLATES[kind];
        if (kind !== "cluster" && !hourOk(template, hours)) continue;
        if (kind === "cluster" && !(hours > 8 && hours < 17)) continue;
        // Everyone of its species at one spot (a 12 m cell) shares one swarm (drawn once, round whichever reports it).
        const cx = (Math.floor(at.x / 12) + 0.5) * 12;
        const cz = (Math.floor(at.z / 12) + 0.5) * 12;
        return {centre: {x: at.x, y: at.y, z: at.z}, seed: hashString(`${slug}#${cx}#${cz}`), t0: epoch - 60, t1: epoch + 60, kind: kind === "cluster" ? "cluster" : "swarm"};
    }
    return null;
}

/** One ambient insect of a swarm (or a cluster): a cloud that dances up and down round its centre, each its own loops. */
export function swarmPoint(centre: P, seed: number, index: number, epoch: number, cluster = false): P {
    const r = rng(hashString(`s${seed}#${index}`));
    const a = r() * Math.PI * 2;
    const f1 = 0.6 + r() * 1.4;
    const f2 = 0.9 + r() * 1.8;
    const p1 = r() * 6.3;
    const p2 = r() * 6.3;
    if (cluster) {
        // Bugs on a warm patch: a tight crawling clump, each shuffling a little.
        const rad = 0.25 * Math.sqrt(r());
        return {x: centre.x + Math.cos(a) * rad + 0.02 * Math.sin(epoch * f1 + p1), y: centre.y + 0.005, z: centre.z + Math.sin(a) * rad + 0.02 * Math.cos(epoch * f2 + p2)};
    }
    const rad = 0.35 + r() * 0.75;
    const t = epoch;
    // The swarm's middle drifts a little; each insect loops round it and bobs (a mayfly's dance).
    const mx = centre.x + 0.4 * Math.sin(t * 0.13 + (seed % 7));
    const mz = centre.z + 0.4 * Math.cos(t * 0.11 + (seed % 5));
    const my = centre.y + 1.4 + 0.25 * Math.sin(t * 0.21 + (seed % 3));
    return {x: mx + Math.cos(a + t * f1 * 0.6) * rad + 0.08 * Math.sin(t * 5.1 * f2 + p2), y: my + 0.55 * Math.sin(t * f2 + p1) * (0.4 + 0.6 * r()), z: mz + Math.sin(a + t * f1 * 0.6) * rad + 0.08 * Math.cos(t * 4.3 * f1 + p1)};
}

/** The dusk emergence (island hours): bats stream out of their roost. */
export const EMERGENCE_HOURS: [number, number] = [17.35, 18.6];
export const EMERGENCE_AMBIENT = 180;

/** Its roost's emergence now (a bat, at dusk), or null: the scene draws its roost-mates streaming out. */
function emergenceFlock(world: ScheduleWorld, owner: TripOwner, kit: ScheduleKit, epoch: number): Flock | null {
    const species = speciesRecipes(owner.slug);
    if (!species.has.has("bat_emergence")) return null;
    const hours = owner.hoursAt(epoch);
    if (hours < EMERGENCE_HOURS[0] || hours > EMERGENCE_HOURS[1]) return null;
    const roost = kit.roostOf(world, owner.profile, owner.animal);
    return {centre: {x: roost.x, y: roost.y, z: roost.z}, seed: hashString(`${owner.animal.id}#roost`), t0: epoch - 60, t1: epoch + 60, kind: "bats"};
}

/**
 * One ambient bat of an emergence: a continuous stream out of the roost (pure in the time: each bat's phase runs round
 * a 24 s cycle), up and away along its own heading with a flutter, gone by about 60 m. Null while it is "inside".
 */
export function emergencePoint(centre: P, seed: number, index: number, epoch: number): (P & {yaw: number}) | null {
    const r = rng(hashString(`b${seed}#${index}`));
    const cycle = 24;
    const phase = (((epoch + (index / EMERGENCE_AMBIENT) * cycle * 7.3 + r() * cycle) % cycle) + cycle) % cycle;
    if (phase > 9) return null;
    const heading = (seed % 360) * (Math.PI / 180) + (r() - 0.5) * 1.6;
    const speed = 4.5 + r() * 2.5;
    const d = phase * speed;
    const wob = 0.8 * Math.sin(phase * (5 + r() * 4) + r() * 6);
    const x = centre.x + Math.sin(heading) * d + Math.cos(heading) * wob;
    const z = centre.z + Math.cos(heading) * d - Math.sin(heading) * wob;
    const y = centre.y - 0.3 + Math.min(phase * 1.6, 9) + 0.6 * Math.sin(phase * 3 + r() * 5);
    return {x, y, z, yaw: heading};
}

/** Mixed flocks: a follower's place in another species' flock or troop now (a window a period, by day), or null. */
const MIXED_SECONDS = 150;
function mixedPose(world: ScheduleWorld, owner: TripOwner, kit: ScheduleKit, base: TripPose, epoch: number): RecipePose | null {
    const list = links.get(owner.animal);
    if (!list) return null;
    for (const l of list) {
        if (l.template !== "mixed_follow" || l.role !== "a") continue;
        const period = Math.floor(epoch / PAIR_PERIOD);
        const start = period * PAIR_PERIOD + (hashString(`${l.key}#${period}`) % (PAIR_PERIOD - MIXED_SECONDS));
        if (epoch < start || epoch >= start + MIXED_SECONDS) continue;
        const hours = owner.hoursAt(start);
        if (!hourOk(TEMPLATES.mixed_follow, hours)) continue;
        const otherTrip = kit.tripAt(world, l.otherProfile, l.other, epoch, owner.hoursAt, l.otherActivity);
        const ownTrip = kit.tripAt(world, owner.profile, owner.animal, epoch, owner.hoursAt, owner.activity);
        if (otherTrip.doing === "sleep" || otherTrip.doing === "to_roost" || ownTrip.doing === "sleep" || ownTrip.doing === "to_roost") continue;
        const other = kit.basePose(world, otherTrip, epoch);
        // In the air only if it flies too; otherwise beside it on the ground, its own seeded place at the flock's side.
        if (other.aloft && !kit.flies(owner.profile)) continue;
        const random = rng(hashString(`${l.key}#mix`));
        const side = (random() < 0.5 ? -1 : 1) * (1.2 + random() * 2.2);
        const back = 0.8 + random() * 2.4;
        const fx = Math.sin(other.yaw);
        const fz = Math.cos(other.yaw);
        const tx = other.x - fx * back + fz * side;
        const tz = other.z - fz * back - fx * side;
        const ty = other.aloft ? other.y + (random() - 0.5) : Math.max(world.sampler.heightAt(tx, tz), 0);
        const k = ease(Math.min(Math.max(Math.min(epoch - start, start + MIXED_SECONDS - epoch) / 12, 0), 1));
        const b = BLOCKS.follow;
        return {
            ...base,
            x: base.x + (tx - base.x) * k,
            y: base.y + (ty - base.y) * k,
            z: base.z + (tz - base.z) * k,
            yaw: base.yaw + wrapAngle(other.yaw - base.yaw) * k,
            moving: other.moving || k < 1,
            aloft: other.aloft && k > 0.5,
            beat: other.aloft && k > 0.5 ? "fly" : "walk",
            act: {episode: `${l.key}#${period}`, recipe: "mixed_follow", block: b.id, state: other.aloft ? "fly" : "walk", u: (epoch - start) / MIXED_SECONDS, pitch: 0, roll: 0, own: k > 0.5, carry: null, prey: null, catch: null, fx: null, mark: null, label: TEMPLATES.mixed_follow.label}
        };
    }
    return null;
}

/** Link the mixed-flock species to the nearest flock or troop of another species (within 40 m, birds with birds). */
function wireMixed(animals: WireInput[]) {
    const social = new Set(["flock", "group", "troop", "herd", "colony"]);
    const taken = new Set<string>();
    const sorted = [...animals].sort((a, b) => a.animal.id.localeCompare(b.animal.id));
    for (const a of sorted) {
        if (!speciesRecipes(a.slug).has.has("mixed_follow") || taken.has(a.animal.id)) continue;
        const flies = (w: WireInput) => w.profile.move === "fly" || w.profile.moves.includes("fly");
        const candidates = sorted.filter((b) => b.slug !== a.slug && social.has(b.profile.social) && flies(b) === flies(a) && Math.hypot(a.animal.home.x - b.animal.home.x, a.animal.home.z - b.animal.home.z) < 40);
        if (!candidates.length) continue;
        const b = candidates.sort((m, n) => Math.hypot(a.animal.home.x - m.animal.home.x, a.animal.home.z - m.animal.home.z) - Math.hypot(a.animal.home.x - n.animal.home.x, a.animal.home.z - n.animal.home.z) || m.animal.id.localeCompare(n.animal.id))[0];
        const key = `mixed_follow#${a.animal.id}#${b.animal.id}`;
        const list = links.get(a.animal) ?? [];
        list.push({template: "mixed_follow", other: b.animal, otherProfile: b.profile, otherSlug: b.slug, otherActivity: b.activity, role: "a", key});
        links.set(a.animal, list);
        taken.add(a.animal.id);
    }
}

/** Molehills round a burrow (pure in its id, spot and the time): a new mound every 5 minutes, each fading over 40. */
export const MOLEHILL_EVERY = 300;
export const MOLEHILL_SECONDS = 2400;
export function molehillsOf(id: string, slug: string, at: P, epoch: number, heightAt: (x: number, z: number) => number): RecipeMark[] {
    if (!enabled || !speciesRecipes(slug).has.has("molehills")) return [];
    const out: RecipeMark[] = [];
    for (let n = Math.floor((epoch - MOLEHILL_SECONDS) / MOLEHILL_EVERY); n <= Math.floor(epoch / MOLEHILL_EVERY); n++) {
        const random = rng(hashString(`${id}#mole#${n}`));
        const from = n * MOLEHILL_EVERY + random() * MOLEHILL_EVERY;
        if (from > epoch || from + MOLEHILL_SECONDS < epoch) continue;
        const a = random() * Math.PI * 2;
        const r = 0.6 + random() * 2.4;
        const x = at.x + Math.sin(a) * r;
        const z = at.z + Math.cos(a) * r;
        const h = heightAt(x, z);
        if (h < 0.02) continue;
        out.push({id: `mole#${id}#${n}`, kind: "mound", x, y: h, z, size: 0.18 + random() * 0.12, from, to: from + MOLEHILL_SECONDS});
    }
    return out;
}

/** Its coat now from its recent acts (pure in its trips): wet after a bathe or a dive, muddy after a wallow, dusty after a dust bath. */
export type RecipeCoat = {wet: number; dust: number};
const COAT_WET = new Set(["bathe", "upend", "dive", "surface", "dive_in", "slide_in", "slip_in", "launch", "scoop", "dive_air", "dive_feet"]);
export function coatOf(world: ScheduleWorld, trips: Trip[], epoch: number, kit: ScheduleKit): RecipeCoat {
    let wet = 0;
    let dust = 0;
    let shookAt = -Infinity;
    let wetAt = -Infinity;
    for (const trip of trips) {
        const owner = (trip as Trip & {owner?: TripOwner | null}).owner;
        if (!owner) continue;
        const episode = stayEpisode(world, trip, owner, kit);
        if (!episode) continue;
        for (const key of episode.keys) {
            if (key.t0 > epoch) continue;
            const since = Math.max(epoch - key.t1, 0);
            const id = key.block.id;
            if (id === "wallow") {
                wet = Math.max(wet, 0.55 * Math.max(1 - since / 1200, 0));
                dust = Math.max(dust, 0.9 * Math.max(1 - since / 1200, 0));
            } else if (id === "dust_bathe" || id === "roll") dust = Math.max(dust, Math.max(1 - since / 900, 0));
            else if (COAT_WET.has(id)) {
                wet = Math.max(wet, Math.max(1 - since / 360, 0));
                wetAt = Math.max(wetAt, key.t1);
            } else if (id === "shake_off") shookAt = Math.max(shookAt, key.t1);
        }
    }
    // A shake after the soaking sheds half of it.
    if (shookAt > wetAt) wet *= 0.5;
    return {wet: Math.min(wet, 1), dust: Math.min(dust, 1)};
}

/** Writes a recipe's coat into the animal-look pass's `arkCoat` (wet, dust), over what that pass set (no-op without it). */
export function applyRecipeCoat(geometry: {getAttribute(name: string): unknown}, index: number, coat: RecipeCoat | null | undefined) {
    if (!coat || (!coat.wet && !coat.dust)) return;
    const attribute = geometry.getAttribute("arkCoat") as {count: number; getX(i: number): number; getY(i: number): number; setXY(i: number, x: number, y: number): void; needsUpdate: boolean} | undefined;
    if (!attribute || index >= attribute.count) return;
    attribute.setXY(index, Math.max(attribute.getX(index), coat.wet), Math.max(attribute.getY(index), coat.dust));
    attribute.needsUpdate = true;
}

/** The duller sex's dim (the material's grey-ward mix, `arkInstance.y`): its saturation drop, additive to `arkVary`. */
export function sexDim(id: string, slug: string): number {
    const look = sexLook(id, slug);
    return look.saturation < 1 ? Math.min((1 - look.saturation) * 1.1, 0.4) : 0;
}

/** For the tests: mixed-flock links of an animal. */
export function wireMixedForTest(animals: WireInput[]) {
    wireMixed(animals);
}
